import fs from 'node:fs';
const rows=[];
const add=(id,title,concept,app,code,expected,tip,mode='run',note='')=>rows.push({id,title,concept,app,code,expected,tip,mode,note});
add('index','เริ่มอ่าน Rust by Example','Rust by Example เรียงแนวคิดผ่านตัวอย่างโค้ด ตั้งแต่การพิมพ์ข้อความจนถึงการจัดการหน่วยความจำและเครื่องมือ','เราจะใช้รายการงาน ไฟล์ตั้งค่า และข้อมูลรายงานเป็นบริบท ตัวอย่างเป็นส่วนย่อยของแอป ไม่ใช่ระบบพร้อมใช้งานทั้งชุด','fn main() { for tasks in [0, 3] { println!("tasks={tasks}"); } }','tasks=0\ntasks=3\n','อ่านตามลำดับเมื่อเจอคำศัพท์ใหม่ แล้วกลับมาค้นหัวข้อที่ต้องใช้ในงาน');
add('hello','ข้อความแรก · Hello World','โปรแกรม executable เริ่มทำงานที่ fn main() ส่วน println! เป็น macro สำหรับพิมพ์ข้อความตามด้วยขึ้นบรรทัดใหม่','แอปบรรทัดคำสั่งควรรายงานว่าเริ่มทำอะไรแล้ว ลองดูผลเมื่อชื่อโครงการต่างกัน','fn main() { for project in ["work", "home"] { println!("Loading {project}"); } }','Loading work\nLoading home\n','เครื่องหมาย ! เป็นส่วนหนึ่งของการเรียก macro ไม่ใช่ชื่อฟังก์ชันธรรมดา');
add('hello/comment','เขียนเหตุผลไว้ในโค้ด · Comments','// ใช้คอมเมนต์จนจบบรรทัด ส่วน /* */ ครอบข้อความหลายบรรทัดและซ้อนได้ /// และ //! ใช้เขียนเอกสาร','เมื่อจำนวนงานที่ยังไม่เสร็จต่างกัน คอมเมนต์ไม่ได้เปลี่ยนค่าที่โปรแกรมคำนวณ','fn main() {\n // Keep finished tasks out of the pending count.\n for done in [1, 3] { println!("pending={}", 5 - done); }\n}','pending=4\npending=2\n','คอมเมนต์อธิบายเหตุผลที่เลือกวิธีนี้ ส่วนชื่อและโค้ดควรบอกว่ากำลังทำอะไร');
add('hello/print','จัดข้อความ · Formatted print','format! สร้าง String ขณะที่ print! และ println! ส่งข้อความไป stdout; eprint! และ eprintln! ส่งไป stderr','รายงานจำนวนงานด้วย placeholder แทนการต่อข้อความเอง','fn main() { for count in [1, 12] { let report = format!("Tasks: {count}"); println!("{report}"); } }','Tasks: 1\nTasks: 12\n','ข้อความแจ้งข้อผิดพลาดของ CLI เหมาะกับ stderr เพื่อไม่ปะปนกับข้อมูล stdout');
add('hello/print/print_debug','ดูข้อมูลระหว่างพัฒนา · Debug','{:?} เรียก Debug; #[derive(Debug)] ให้ compiler สร้าง implementation สำหรับชนิดข้อมูลที่รองรับ','ตรวจข้อมูลรายการงานก่อนออกแบบรูปแบบข้อความสำหรับผู้ใช้','#[derive(Debug)]\nstruct Task { done: bool }\nfn main() { for done in [false, true] { println!("{:?}", Task { done }); } }','Task { done: false }\nTask { done: true }\n','รูปแบบ Debug มีไว้ดูข้อมูลขณะพัฒนา อย่าใช้เป็นสัญญารูปแบบไฟล์ถาวร');
add('hello/print/print_display','ข้อความที่ผู้ใช้จะเห็น · Display','{} เรียก Display ซึ่งต้องเขียนวิธี format เองเมื่อเป็นชนิดข้อมูลที่สร้างขึ้น; derive ไม่ได้สร้าง Display ให้','แปลงสถานะงานเป็นข้อความที่อ่านรู้เรื่องโดยไม่เปิดเผยโครงสร้างภายใน','use std::fmt;\nstruct Status(bool);\nimpl fmt::Display for Status { fn fmt(&self, f: &mut fmt::Formatter<\'_>) -> fmt::Result { write!(f, "{}", if self.0 { "done" } else { "pending" }) } }\nfn main() { println!("{} / {}", Status(false), Status(true)); }','pending / done\n','คืน fmt::Result และส่งต่อข้อผิดพลาดจาก write! อย่ากลืนผลลัพธ์ของการเขียน');
add('hello/print/print_display/testcase_list','แสดงรายการโดยไม่เหลือจุลภาคท้าย · List','Display ของชนิดหุ้ม Vec สามารถวนสมาชิกแล้วเขียนตัวคั่นเฉพาะก่อนสมาชิกตั้งแต่ตัวที่สอง','ใช้แสดงเลขงานที่เลือกสำหรับรายงาน CLI และรองรับรายการว่าง','use std::fmt;\nstruct Selected(Vec<u32>);\nimpl fmt::Display for Selected { fn fmt(&self, f: &mut fmt::Formatter<\'_>) -> fmt::Result { for (i,n) in self.0.iter().enumerate() { if i > 0 { write!(f, ", ")?; } write!(f, "{n}")?; } Ok(()) } }\nfn main() { println!("[{}]", Selected(vec![])); println!("[{}]", Selected(vec![2, 8])); }','[]\n[2, 8]\n','ทดสอบรายการว่าง หนึ่งตัว และหลายตัวเมื่อเขียนตัวคั่น');
add('hello/print/fmt','ควบคุมความกว้างและความละเอียด · Formatting','format string ระบุความกว้าง การเติมศูนย์ จำนวนทศนิยม และฐานตัวเลขได้ รูปแบบที่รับได้ขึ้นกับ trait ของค่า','แสดงเลขงานสามหลัก และค่าที่วัดได้สองตำแหน่งทศนิยม','fn main() { for id in [7, 42] { println!("TASK-{id:03}"); } for progress in [1.0, 1.234] { println!("{progress:.2}"); } }','TASK-007\nTASK-042\n1.00\n1.23\n','การแสดงทศนิยมเป็นเรื่องรูปแบบข้อความ ไม่ใช่การรับประกันความแม่นยำทางการเงิน');
add('primitives','ชนิดข้อมูลพื้นฐาน · Primitives','Rust มีจำนวนเต็ม จำนวนทศนิยม bool char tuple และ array; binding ต้องมีชนิดแน่นอน แม้ compiler จะอนุมานให้ได้','ใช้ bool เก็บสถานะ และจำนวนเต็มเก็บจำนวนงานให้เหมาะกับความหมาย','fn main() { let done: bool = false; let tasks: u32 = 3; println!("{tasks} {done}"); println!("{} {}", tasks + 2, !done); }','3 false\n5 true\n','เลือกชนิดจากช่วงค่าและความหมาย ไม่จำเป็นต้องใช้ชนิดใหญ่ที่สุดทุกครั้ง');
add('primitives/literals','ค่าคงรูปและตัวดำเนินการ · Literals','literal ใส่ suffix ชนิดและตัวคั่น _ ได้; ตัวดำเนินการเปรียบเทียบให้ bool และการหารจำนวนเต็มตัดส่วนเศษ','คำนวณจำนวนหน้ารายงานจากจำนวนแถว โดยสังเกตผลหารจำนวนเต็ม','fn main() { for rows in [10_u32, 11_u32] { println!("{} {}", rows / 5, rows % 5); } }','2 0\n2 1\n','เมื่อแบ่งหน้า อย่าลืมจัดการแถวที่เหลือจาก % และตรวจว่าตัวหารไม่เป็นศูนย์');
add('primitives/tuples','คืนค่าหลายชนิดพร้อมกัน · Tuples','tuple เก็บหลายค่าคนละชนิดในลำดับคงที่ อ่านด้วย .0 .1 หรือแยกค่าด้วย pattern','สรุปจำนวนงานทั้งหมดกับจำนวนที่เสร็จเป็นค่าคู่','fn summary(done: u32) -> (u32, bool) { (done, done == 3) }\nfn main() { for done in [1, 3] { let (count, complete) = summary(done); println!("{count} {complete}"); } }','1 false\n3 true\n','เมื่อค่าคู่เริ่มมีความหมายหลายช่อง ใช้ struct ที่ตั้งชื่อ field ชัดเจน');
add('primitives/array','ข้อมูลต่อเนื่อง · Arrays และ Slices','array มีความยาวเป็นส่วนหนึ่งของชนิด; slice คือมุมมองข้อมูลต่อเนื่องที่ยืมมา โดยความยาวทราบขณะรัน','ฟังก์ชันรวมจำนวนงานแต่ละวันรับ slice จึงใช้ได้กับช่วงข้อมูลหลายขนาด','fn total(days: &[u32]) -> u32 { days.iter().sum() }\nfn main() { let days = [2, 4, 6]; println!("{}", total(&days)); println!("{}", total(&days[..2])); }','12\n6\n','ใช้ get เมื่อ index มาจากผู้ใช้ เพื่อรับ Option แทนการ panic เมื่อหลุดขอบเขต');
add('custom_types','สร้างชนิดที่ตรงกับงาน · Custom Types','struct รวม field ที่อยู่ด้วยกัน ส่วน enum แทนทางเลือกของข้อมูล แต่ละ variant อาจมีข้อมูลต่างกัน','โมเดลงานด้วยชื่อและสถานะ แทนการใช้ตัวเลขที่ต้องจำความหมาย','struct Task { title: String, done: bool }\nfn main() { for done in [false, true] { let task = Task { title: "backup".into(), done }; println!("{} {}", task.title, task.done); } }','backup false\nbackup true\n','ออกแบบชนิดให้สื่อข้อจำกัดของงาน ก่อนเพิ่มเงื่อนไขกระจายหลายที่');
add('custom_types/structs','ข้อมูลหนึ่งรายการ · Structures','struct แบบ field มีชื่อ อ่านและสร้างด้วยชื่อ field ได้; ยังมี tuple struct และ unit struct สำหรับรูปแบบอื่น','รวมชื่อกับเวลาประเมินของงาน เพื่อส่งให้ฟังก์ชันเป็นหน่วยเดียว','struct Task { title: &\'static str, minutes: u32 }\nfn main() { for minutes in [15, 30] { let task = Task { title: "review", minutes }; println!("{}: {}m", task.title, task.minutes); } }','review: 15m\nreview: 30m\n','struct update syntax อาจ move field ที่ไม่ใช่ Copy จากค่าต้นทาง');
add('custom_types/enum','สถานะที่เลือกได้ · Enums','enum แทนค่าหนึ่ง variant ในขณะหนึ่ง และ match แยกการทำงานตาม variant ได้อย่างครบถ้วน','สถานะงานอาจรอทำหรือเสร็จแล้วพร้อมเลขรายงาน','enum State { Pending, Done(u32) }\nfn main() { for state in [State::Pending, State::Done(8)] { match state { State::Pending => println!("pending"), State::Done(id) => println!("report={id}") } } }','pending\nreport=8\n','ใช้ข้อมูลที่ผูกกับ variant แทน field เสริมที่อาจไม่สอดคล้องกับสถานะ');
add('custom_types/enum/enum_use','ย่อชื่อ variant · use','use นำชื่อเข้ามาใน scope จึงเรียก variant โดยไม่ต้องใส่ชื่อ enum นำหน้าทุกครั้ง','ลดความยาวของ match สถานะงาน โดยยังเลือก import เฉพาะชื่อที่ใช้','enum State { Pending, Done }\nuse State::{Pending, Done};\nfn main() { for s in [Pending, Done] { println!("{}", match s { Pending => "wait", Done => "ok" }); } }','wait\nok\n','หลีกเลี่ยง glob import เมื่อชื่ออย่าง Error หรือ Done ชนกันหลายโมดูล');
add('custom_types/enum/c_like','enum กับรหัสตัวเลข · C-like','enum ที่ไม่มี payload กำหนด discriminant ได้ และ cast เป็นจำนวนเต็มได้; ไม่ได้แปลว่าแปลงจำนวนใดกลับเป็น enum ได้โดยตรง','กำหนดรหัสสถานะที่โปรโตคอลภายในต้องใช้','enum Code { Pending = 10, Done = 20 }\nfn main() { println!("{}", Code::Pending as u8); println!("{}", Code::Done as u8); }','10\n20\n','ค่าที่รับจากภายนอกควรตรวจด้วย match หรือ TryFrom ก่อนสร้างสถานะ');
add('custom_types/enum/testcase_linked_list','ข้อมูลต่อกันด้วย Box · Linked list','ชนิด recursive ต้องมี indirection อย่าง Box เพื่อให้ขนาดชนิดทราบขณะคอมไพล์; enum แยกโหนดกับจุดจบได้','ดูโครงสร้างคิวงานอย่างย่อ โดยเพิ่มหัวคิวแล้วนับสมาชิก','enum Queue { End, Item(u32, Box<Queue>) }\nimpl Queue { fn len(&self) -> usize { match self { Self::End => 0, Self::Item(_, tail) => 1 + tail.len() } } }\nfn main() { let q = Queue::End; println!("{}", q.len()); let q = Queue::Item(7, Box::new(q)); if let Queue::Item(id, _) = &q { println!("{id}: {}", q.len()); } }','0\n7: 1\n','ตัวอย่างนี้สอน recursive type; ไม่ใช่ข้อสรุปว่า linked list เหมาะกว่าคอลเลกชันมาตรฐาน');
add('custom_types/constants','ค่าที่ใช้ร่วมกัน · constants','const ต้องระบุชนิด และใช้แทนค่าคงที่; static เป็นตำแหน่งเก็บข้อมูลที่มีอายุทั้งโปรแกรม','กำหนดขนาดหน้ารายงานที่ใช้เหมือนกันหลายฟังก์ชัน','const PAGE_SIZE: u32 = 10;\nfn main() { for pages in [1, 3] { println!("{}", pages * PAGE_SIZE); } }','10\n30\n','ค่าคงที่เหมาะกับค่าที่ไม่ต้องอ่านจากการตั้งค่าของผู้ใช้');
add('variable_bindings','ตั้งชื่อให้ค่า · Variable bindings','let ผูกชื่อกับค่า โดยปกติ binding เปลี่ยนค่าไม่ได้; compiler ใช้บริบทอนุมานชนิดได้','ตั้งชื่อจำนวนงานก่อนนำไปสร้างข้อความรายงาน','fn main() { let tasks = 3; println!("{tasks}"); let tasks = tasks + 2; println!("{tasks}"); }','3\n5\n','binding ใหม่ที่ใช้ชื่อเดิมคือ shadowing ไม่ใช่การแก้ binding เดิม');
add('variable_bindings/mut','แก้ค่าอย่างตั้งใจ · Mutability','let mut อนุญาตให้อัปเดตค่าของ binding เดิม โดยชนิดยังคงเดิม','สะสมจำนวนงานที่เสร็จระหว่างประมวลผล','fn main() { let mut done = 0; for count in [2, 3] { done += count; println!("{done}"); } }','2\n5\n','ใช้ mut เฉพาะเมื่อมีการแก้ค่าจริง เพื่อให้จุดเปลี่ยนสถานะมองเห็นง่าย');
add('variable_bindings/scope','ขอบเขตชื่อและการบังชื่อ · Scope','binding อยู่ภายใน scope ที่ประกาศ; ชื่อใหม่ใน scope ย่อยอาจบังชื่อภายนอก และชื่อเดิมกลับมาเมื่อออก scope','ปรับค่ารายงานชั่วคราวโดยไม่เปลี่ยนค่าหลัก','fn main() { let limit = 10; { let limit = 3; println!("{limit}"); } println!("{limit}"); }','3\n10\n','อย่าให้ shadowing หลายชั้นทำให้ไม่รู้ว่าค่ามาจากไหน');
add('variable_bindings/declare','ประกาศก่อนกำหนดค่า · Declare first','Rust ยอมประกาศ binding ก่อนมีค่า แต่ต้องพิสูจน์ได้ว่ากำหนดค่าก่อนอ่านทุกเส้นทาง','เลือกขนาดรายงานตามโหมดแล้วใช้งานภายหลัง','fn main() { for compact in [true, false] { let limit; if compact { limit = 5; } else { limit = 20; } println!("{limit}"); } }','5\n20\n','เมื่อทำได้ ใช้ if expression สร้างค่าใน let เดียว จะตามรอยง่ายกว่า');
add('variable_bindings/freeze','บังชื่อ mutable ด้วยชื่อ immutable · Freezing','binding immutable ที่บังชื่อ mutable ทำให้แก้ผ่านชื่อนั้นไม่ได้ใน scope ย่อย แต่ไม่ได้เปลี่ยนคุณสมบัติของ binding ภายนอก','ดูค่าจำนวนงานในช่วงที่ไม่ต้องการแก้มัน','fn main() { let mut count = 1; { let count = count; println!("{count}"); } count += 1; println!("{count}"); }','1\n2\n','freeze ในตัวอย่างคือผลของ shadowing ไม่ใช่คำสั่ง lock ข้อมูล');
import { build } from './import-source-build.mjs';

add('types','ชนิดที่ compiler ต้องรู้ · Types','ชนิดของ binding กำหนดว่าทำอะไรกับค่าได้ และไม่เปลี่ยนตามค่าที่ใส่ภายหลัง','ให้จำนวนงานเป็น u32 เพื่อแยกจากชื่อที่เป็นข้อความ','fn main() { let a: u32 = 2; let b: u32 = 5; println!("{}", a + b); println!("{}", b - a); }','7\n3\n','การอนุมานชนิดลดข้อความที่ต้องเขียน แต่ไม่ได้ทำให้ Rust เป็น dynamic typing');
add('types/cast','แปลงด้วย as · Casting','as ใช้แปลงชนิดตัวเลขตามกฎของภาษา การแปลงให้เล็กลงอาจสูญเสียข้อมูล','ดูว่ารหัสที่เกินช่วง u8 เปลี่ยนไปอย่างไรเมื่อ cast','fn main() { for id in [255_u16, 256] { println!("{id} -> {}", id as u8); } }','255 -> 255\n256 -> 0\n','เมื่อค่าจากภายนอกต้องไม่สูญหาย ใช้ TryFrom และรับมือกรณีเกินช่วง');
add('types/literals','ระบุชนิดที่ literal · Literals','suffix เช่น u32 หรือ f64 ทำให้ชนิดของ literal ชัดเจน; ค่าที่ไม่ระบุใช้บริบทช่วยอนุมาน','กำหนดตัวเลขตัวอย่างให้เหมือนชนิด field ในแอป','fn main() { let small = 2_u8; let large = 2_u64; println!("{} {}", std::mem::size_of_val(&small), std::mem::size_of_val(&large)); }','1 8\n','ขนาดของ usize ขึ้นกับ target ต่างจากชนิดจำนวนเต็มที่ระบุจำนวนบิต');
add('types/inference','อนุมานชนิดจากการใช้ · Inference','compiler ใช้การใช้งานภายหลังช่วยอนุมานชนิดได้ เช่น push ค่าลง Vec ที่ยังไม่ได้ระบุชนิด','เริ่มรายการเลขงานว่าง แล้วเพิ่มข้อมูลที่กำหนดชนิดสมาชิก','fn main() { let mut ids = Vec::new(); ids.push(3_u16); ids.push(9); println!("{:?}", ids); }','[3, 9]\n','ถ้าบริบทไม่พอ ระบุชนิดตรง let หรือ generic argument แทนการเดา');
add('types/alias','ตั้งชื่อแทนชนิด · Aliasing','type สร้างชื่อแทนชนิดเดิม ไม่ได้สร้างชนิดใหม่ที่ compiler แยกออกจากกัน','ชื่อ TaskId ช่วยสื่อความหมายใน signature แต่ยังรับ u64 ทั่วไปได้','type TaskId = u64;\nfn main() { let id: TaskId = 7; let ordinary: u64 = id; println!("{} {}", id, ordinary + 1); }','7 8\n','ถ้าต้องกันการสลับ UserId กับ TaskId ให้ใช้ newtype struct');
add('conversion','แปลงค่าผ่าน trait · Conversion','From และ Into ใช้เมื่อการแปลงตามสัญญาไม่ล้มเหลว; TryFrom และ TryInto คืนข้อผิดพลาดได้','แยกการรับค่าภายนอกออกจากชนิดข้อมูลภายใน','fn main() { let small = 12_u8; let wide = u32::from(small); println!("{wide}"); println!("{}", u8::try_from(300_u32).is_err()); }','12\ntrue\n','เลือกชนิดการแปลงจากความเป็นไปได้ที่จะผิดพลาด');
add('conversion/from_into','แปลงที่ไม่ล้มเหลว · From / Into','เมื่อ implement From<T> ให้ U จะมี Into<U> สำหรับ T ผ่าน blanket implementation','หุ้มเลขงานให้มีความหมายและรับค่าจากจำนวนเต็ม','struct TaskId(u32);\nimpl From<u32> for TaskId { fn from(value: u32) -> Self { Self(value) } }\nfn main() { let a = TaskId::from(3); let b: TaskId = 8_u32.into(); println!("{} {}", a.0, b.0); }','3 8\n','เขียน From เป็นหลักเมื่อเป็นเจ้าของชนิดปลายทาง แล้วใช้ Into ที่ฝั่งเรียก');
add('conversion/try_from_try_into','แปลงพร้อมตรวจช่วง · TryFrom / TryInto','TryFrom คืน Result เพื่อให้ผู้เรียกรับมือค่าที่แปลงไม่ได้','รับค่าขนาดหน้าในชนิดเล็ก โดยปฏิเสธจำนวนที่เกินช่วง','fn main() { for size in [10_u16, 300] { match u8::try_from(size) { Ok(v) => println!("size={v}"), Err(_) => println!("out of range") } } }','size=10\nout of range\n','อย่าเปลี่ยนการแปลงที่ควรตรวจช่วงเป็น as เพียงเพื่อให้คอมไพล์ผ่าน');
add('conversion/string','ข้อความกับค่าที่มีชนิด · String conversion','Display ทำให้ใช้ to_string ได้ ส่วน parse ใช้ FromStr และคืน Result เพราะข้อความอาจไม่ตรงชนิด','อ่านจำนวนงานจากไฟล์ตั้งค่าที่เป็นข้อความ','fn main() { for raw in ["12", "many"] { match raw.parse::<u32>() { Ok(n) => println!("{n}"), Err(_) => println!("invalid number") } } }','12\ninvalid number\n','ระบุชนิดที่ต้องการ parse ให้ชัดและส่งข้อผิดพลาดพร้อมชื่อการตั้งค่า');
add('expression','บล็อกคืนค่าได้ · Expressions','บล็อกเป็น expression ได้ ค่าสุดท้ายที่ไม่มี ; เป็นผลลัพธ์; ถ้าเติม ; จะได้ ()','เลือกข้อความสรุปจากจำนวนงานโดยกำหนดค่าใน let เดียว','fn main() { for count in [0, 2] { let label = { if count == 0 { "empty" } else { "ready" } }; println!("{label}"); } }','empty\nready\n','ตรวจ ; ท้ายบล็อกเมื่อ compiler บอกว่าคาดหวังชนิดหนึ่งแต่พบ ()');
add('flow_control','เลือกทางและทำซ้ำ · Flow of Control','if เลือกเส้นทาง match จับรูปแบบ ส่วน loop while และ for ทำซ้ำภายใต้เงื่อนไขต่างกัน','ประมวลผลรายการงานตามสถานะของแต่ละรายการ','fn main() { for done in [false, true] { if done { println!("archive"); } else { println!("keep"); } } }','keep\narchive\n','เลือกโครงสร้างที่สะท้อนเงื่อนไขหยุดและรูปแบบข้อมูลชัดที่สุด');
add('flow_control/if_else','เงื่อนไขคืนค่า · if / else','เงื่อนไข if ต้องเป็น bool และแขนงที่ใช้เป็นค่าต้องให้ชนิดที่เข้ากันได้','เลือกขนาดชุดประมวลผลจากโหมด compact','fn main() { for compact in [true, false] { let batch = if compact { 5 } else { 20 }; println!("{batch}"); } }','5\n20\n','Rust ไม่แปลงจำนวนศูนย์หรือข้อความว่างให้เป็น bool โดยอัตโนมัติ');
add('flow_control/loop','ทำซ้ำจนสั่งหยุด · loop','loop ทำซ้ำไม่จำกัดจนพบ break; continue เริ่มรอบใหม่','จำลองการประมวลผลงานทีละชิ้นจนเหลือศูนย์','fn main() { let mut left = 2; loop { println!("left={left}"); if left == 0 { break; } left -= 1; } }','left=2\nleft=1\nleft=0\n','ตัวอย่าง retry จริงต้องมีเงื่อนไขหยุดและจัดการข้อผิดพลาดด้วย');
add('flow_control/loop/nested','หยุดลูปที่ต้องการ · Labels','label เช่น \'projects: ระบุว่าคำสั่ง break หรือ continue หมายถึงลูปใดเมื่อซ้อนกัน','หยุดค้นหาทั้งโครงการทันทีเมื่อเจอเลขงานที่ต้องการ','fn main() { \'projects: for project in [1, 2] { for task in [3, 4] { println!("{project}:{task}"); if task == 4 { break \'projects; } } } }','1:3\n1:4\n','ตั้งชื่อ label ตามความหมายของลูป แทนชื่อ outer ที่ต้องไล่อ่านตำแหน่ง');
add('flow_control/loop/return','คืนค่าจากลูป · break value','break value ทำให้ loop expression ส่งค่านั้นออกมาได้','ค้นหา slot ว่างแรกจากตัวนับที่เพิ่มขึ้น','fn main() { for occupied in [0, 2] { let mut slot = 0; let free = loop { if slot >= occupied { break slot; } slot += 1; }; println!("{free}"); } }','0\n2\n','การคืนค่าด้วย break ใช้กับ loop ไม่ใช่ค่าผลลัพธ์จาก for หรือ while');
add('flow_control/while','ทำซ้ำขณะเงื่อนไขจริง · while','while ตรวจ bool ก่อนทุกรอบ และอาจไม่ทำงานเลยถ้าเงื่อนไขแรกเป็น false','ระบายจำนวนงานค้างทีละรายการ','fn main() { for initial in [0, 2] { let mut left = initial; while left > 0 { println!("{left}"); left -= 1; } println!("done"); } }','done\n2\n1\ndone\n','เช็กว่าทุกรอบขยับเข้าใกล้เงื่อนไขหยุด หรือมีทางออกอื่น');
add('flow_control/for','วน iterator · for และ range','for วนค่าจาก IntoIterator; a..b ไม่รวม b ส่วน a..=b รวมปลายทั้งสอง','สร้างเลขหน้ารายงานโดยดูความต่างของขอบเขต','fn main() { for page in 1..3 { println!("exclusive={page}"); } for page in 1..=3 { println!("inclusive={page}"); } }','exclusive=1\nexclusive=2\ninclusive=1\ninclusive=2\ninclusive=3\n','เลือก iter, iter_mut หรือ into_iter ตามว่าต้องการยืม แก้ผ่านการยืม หรือรับ ownership');
add('flow_control/match','แยกทุกกรณี · match','match เลือกแขนงจาก pattern และต้องครอบคลุมค่าที่เป็นไปได้ทั้งหมด','จำแนกจำนวนงานที่ค้างเพื่อสร้างข้อความแจ้งสถานะ','fn main() { for pending in [0, 1, 5] { println!("{}", match pending { 0 => "empty", 1 => "one", _ => "many" }); } }','empty\none\nmany\n','ใช้ match กับ enum เพื่อให้ compiler ช่วยเตือนเมื่อเพิ่ม variant แล้วลืมจัดการ');
add('flow_control/match/destructuring','แยกข้อมูลด้วย pattern · Destructuring','pattern แยกส่วนของ tuple array struct และ enum พร้อมเลือกเงื่อนไขการจับได้','อ่านชื่อและสถานะจากข้อมูลหนึ่งรายการโดยไม่ใช้ index กระจาย','fn main() { for task in [("backup", false), ("report", true)] { let (name, done) = task; println!("{name} {done}"); } }','backup false\nreport true\n','pattern ที่อาจจับไม่สำเร็จต้องอยู่ในบริบทที่รับมือกรณีไม่ตรง เช่น match หรือ if let');
add('flow_control/match/destructuring/destructure_tuple','จับรูปแบบ tuple','tuple pattern จับแต่ละตำแหน่งได้ ใช้ _ ข้ามค่าหนึ่งและ .. ข้ามส่วนที่เหลือ','เลือกข้อความจากคู่ชื่อโครงการกับจำนวนงาน','fn main() { for item in [("home", 0), ("work", 3)] { match item { (name, 0) => println!("{name}: empty"), (name, n) => println!("{name}: {n}") } } }','home: empty\nwork: 3\n','ถ้าต้องจำว่าตำแหน่งไหนคืออะไรหลายจุด ให้พิจารณา struct');
add('flow_control/match/destructuring/destructure_slice','จับ array และ slice','slice pattern แยกหัว ท้าย และส่วนกลางด้วย .. ได้โดยตรวจความยาวให้ด้วย','แสดงชื่อคำสั่งแรก หรือแจ้งว่าไม่มี argument','fn main() { for args in [&[][..], &["list", "all"][..]] { match args { [] => println!("no command"), [command, rest @ ..] => println!("{command} {}", rest.len()) } } }','no command\nlist 1\n','pattern ตรวจจำนวนสมาชิกให้ แต่การแปล argument ยังต้องตรวจความหมายเอง');
add('flow_control/match/destructuring/destructure_enum','แยกข้อมูลใน enum','แต่ละ variant อาจมีรูปแบบข้อมูลไม่เหมือนกัน match แยกพร้อมผูกข้อมูลภายในกับชื่อได้','คำสั่งงานหนึ่งอาจเพิ่มงานหรือขอให้นับงาน','enum Command { Add(&\'static str), Count }\nfn main() { for c in [Command::Add("backup"), Command::Count] { match c { Command::Add(name) => println!("add {name}"), Command::Count => println!("count") } } }','add backup\ncount\n','ให้ enum เก็บข้อมูลที่จำเป็นของแต่ละคำสั่งไว้ด้วยกัน');
add('flow_control/match/destructuring/destructure_pointers','แยก reference กับ ref pattern','& ใน pattern จับรูปแบบ reference ส่วน ref สร้าง reference ให้ binding; ทั้งสองมีหน้าที่ต่างกัน','อ่านจำนวนงานผ่านการยืมโดยไม่ย้ายข้อมูลต้นทาง','fn main() { for n in [2, 5] { let borrowed = &n; let &count = borrowed; println!("{} {}", count, *borrowed); } }','2 2\n5 5\n','อย่าสับสน * สำหรับ dereference expression กับ & หรือ ref ใน pattern');
add('flow_control/match/destructuring/destructure_structures','แยก field ของ struct','struct pattern เลือก field ที่ต้องการและใช้ .. ข้าม field อื่นได้','รายงานจำนวนงานโดยไม่ต้องอ่านชื่อโครงการในจุดนี้','struct Summary { project: &\'static str, pending: u32 }\nfn main() { for pending in [0, 4] { let s = Summary { project: "work", pending }; let Summary { pending: count, .. } = s; println!("{count}"); } }','0\n4\n','ใช้ชื่อใหม่ใน field pattern เมื่อช่วยให้บทบาทของค่าชัดขึ้น');
add('flow_control/match/guard','เงื่อนไขเพิ่มในแขนง · Guards','match guard เป็น if หลัง pattern ใช้ตรวจเงื่อนไขที่ pattern อย่างเดียวไม่พอ','จัดระดับจำนวนงานตามเกณฑ์ที่เปลี่ยนได้','fn main() { let limit = 3; for n in [2, 5] { println!("{}", match n { count if count > limit => "busy", _ => "normal" }); } }','normal\nbusy\n','guard ไม่ทำให้ compiler ถือว่า pattern ครอบคลุมทุกค่าที่เป็นไปได้');
add('flow_control/match/binding','ตั้งชื่อค่าที่จับได้ · @ binding','name @ pattern ผูกชื่อกับค่าพร้อมจำกัดรูปแบบที่ยอมรับ','รับเลขความสำคัญเฉพาะช่วงที่ระบบรองรับ','fn main() { for level in [2, 8] { match level { valid @ 1..=3 => println!("priority={valid}"), _ => println!("invalid") } } }','priority=2\ninvalid\n','ใช้ @ เมื่อทั้งต้องตรวจ pattern และใช้ค่าที่จับได้ในแขนง');
add('flow_control/if_let','สนใจเพียง pattern เดียว · if let','if let จัดการกรณีที่ตรง pattern เดียวได้โดยไม่ต้องเขียน match เต็มชุด','อ่านเลขงานที่อาจยังไม่มีค่า แล้วแสดงเฉพาะเมื่อมี','fn main() { for id in [None, Some(7)] { if let Some(id) = id { println!("task={id}"); } else { println!("no selection"); } } }','no selection\ntask=7\n','ใช้ match เมื่อทุก variant ต้องมีการทำงานที่สำคัญ');
add('flow_control/let_else','แยกกรณีใช้ไม่ได้ออกก่อน · let-else','let pattern = expression else ต้องออกจากเส้นทางปัจจุบัน เช่น return; binding ที่จับได้ใช้ต่อใน scope ด้านนอกได้','ปฏิเสธคำขอที่ไม่มีเลขงาน แล้วทำงานกรณีปกติต่อ','fn show(id: Option<u32>) { let Some(id) = id else { println!("missing id"); return; }; println!("task={id}"); }\nfn main() { show(None); show(Some(9)); }','missing id\ntask=9\n','ใช้เมื่อต้องการลดการซ้อนบล็อกหลังตรวจ input');
add('flow_control/while_let','วนขณะที่ยังจับ pattern ได้ · while let','while let ทำซ้ำตราบใดที่ expression ยังตรง pattern ที่กำหนด','หยิบงานจาก stack จนไม่มีงานเหลือ','fn main() { let mut tasks = vec![1, 2]; while let Some(id) = tasks.pop() { println!("task={id}"); } println!("left={}", tasks.len()); }','task=2\ntask=1\nleft=0\n','Vec::pop หยิบท้ายรายการ ถ้าต้องการคิวหน้าก่อนให้พิจารณา VecDeque');
add('fn','แบ่งงานเป็นฟังก์ชัน · Functions','fn ระบุชนิด parameter และชนิดคืนค่า; expression ท้ายฟังก์ชันคืนค่าได้โดยไม่ต้องเขียน return ส่วนฟังก์ชันที่ไม่ระบุผลลัพธ์คืน ()','แยกการคำนวณงานค้างออกจากข้อความแสดงผล เพื่อใช้ซ้ำกับรายงานหลายแบบ','fn pending(total: u32, done: u32) -> u32 { total - done }\nfn main() { println!("{}", pending(5, 2)); println!("{}", pending(5, 5)); }','3\n0\n','ตัวอย่างนี้สมมติว่า done ไม่เกิน total; input ภายนอกต้องตรวจเงื่อนไขนี้');
add('fn/methods','พฤติกรรมของข้อมูล · Methods','impl วาง associated function และ method; method มี self เป็น receiver โดย self รับ ownership, &self ยืมอ่าน และ &mut self ยืมแก้','ให้งานมี method สำหรับปิดงาน แทนการแก้ field กระจาย','struct Task { done: bool }\nimpl Task { fn new() -> Self { Self { done: false } } fn finish(&mut self) { self.done = true; } }\nfn main() { let mut task = Task::new(); println!("{}", task.done); task.finish(); println!("{}", task.done); }','false\ntrue\n','เลือก receiver ตามการเข้าถึงที่ต้องใช้จริง');
add('fn/closures','ฟังก์ชันที่จำค่ารอบตัว · Closures','closure เขียนเป็น |parameter| expression และจับค่าจาก environment ได้ ชนิด input/output มักอนุมานจากการใช้','ใช้ค่าเกณฑ์จากหน้าตั้งค่ามากรองจำนวนงาน','fn main() { let limit = 3; let busy = |count| count > limit; println!("{}", busy(2)); println!("{}", busy(5)); }','false\ntrue\n','closure แต่ละตัวมีชนิดเฉพาะตัว แม้หน้าตาคล้ายกัน');
add('fn/closures/capture','จับค่าโดยยืมหรือย้าย · Capturing','closure อาจจับด้วย &T, &mut T หรือย้ายค่า ขึ้นกับสิ่งที่ body ทำ; move บังคับให้จับโดยค่า','ตัวนับงานต้องยืมแบบแก้ไขได้ระหว่างที่ closure ยังใช้งานอยู่','fn main() { let mut done = 0; { let mut finish = || { done += 1; println!("{done}"); }; finish(); finish(); } println!("final={done}"); }','1\n2\nfinal=2\n','move ไม่ได้หมายความว่า closure เรียกได้ครั้งเดียวเสมอไป ดูว่ามันย้ายค่าที่จับออกจาก body หรือไม่');
add('fn/closures/input_parameters','รับ closure เป็น parameter','Fn ใช้ shared receiver, FnMut แก้ environment ได้ และ FnOnce อาจใช้ค่าที่จับหมดไป; Fn เป็นข้อจำกัดที่เข้มกว่าในการรับ closure','ให้ฟังก์ชันรายงานรับวิธีจัดข้อความจากผู้เรียก','fn report<F: Fn(u32) -> String>(format: F) { println!("{}", format(2)); println!("{}", format(5)); }\nfn main() { let prefix = "tasks"; report(|n| format!("{prefix}={n}")); }','tasks=2\ntasks=5\n','ใช้ bound ที่ต้องการจริง ถ้าเรียกเพียงครั้งเดียว FnOnce อาจยืดหยุ่นกว่า');
add('fn/closures/anonymity','ชนิดที่ไม่มีชื่อให้เขียน · Type anonymity','compiler สร้างชนิดเฉพาะสำหรับแต่ละ closure การรับแบบ generic พร้อม Fn bound จึงรับชนิดที่ไม่ต้องระบุชื่อได้','ฟังก์ชันเดียวรับตัวตรวจงานต่างเกณฑ์กันได้โดยไม่สร้าง trait เฉพาะแอป','fn check<F: Fn(u32) -> bool>(f: F) { println!("{}", f(3)); }\nfn main() { check(|n| n > 2); check(|n| n > 5); }','true\nfalse\n','อย่าคิดว่า closure ที่เขียนเหมือนกันจะมีชนิดเดียวกัน');
add('fn/closures/input_functions','ส่งฟังก์ชันแทน closure','ฟังก์ชันที่เข้ากับ signature ใช้กับ parameter ที่มี Fn bound ได้ จึงไม่จำเป็นต้องห่อด้วย closure ทุกครั้ง','ใช้ตัวตรวจที่ตั้งชื่อไว้แล้วร่วมกับเครื่องมือรายงาน','fn urgent(n: u32) -> bool { n > 3 }\nfn show<F: Fn(u32) -> bool>(f: F) { println!("{} {}", f(2), f(5)); }\nfn main() { show(urgent); show(|n| n == 2); }','false true\ntrue false\n','ใช้ฟังก์ชันมีชื่อเมื่อเงื่อนไขยาวหรือมีหลายที่ใช้');
add('fn/closures/output_parameters','คืน closure จากฟังก์ชัน','impl Fn... ซ่อนชนิด closure ที่คืนได้ และ move ย้ายค่าที่ต้องอยู่ต่อเข้าไปใน closure','สร้างตัวตรวจจำนวนงานจากเกณฑ์ตั้งค่าของแต่ละโครงการ','fn over(limit: u32) -> impl Fn(u32) -> bool { move |count| count > limit }\nfn main() { let over_three = over(3); let over_ten = over(10); println!("{} {}", over_three(5), over_ten(5)); }','true false\n','ค่าที่คืนแบบ impl Trait ต้องเป็นชนิด concrete เดียวกันในทุกเส้นทางคืนค่า');
add('fn/closures/closure_examples','ใช้ closure กับ std','method ของ iterator ใน std รับ closure เพื่อกำหนดการค้นหาและเงื่อนไขโดยไม่ต้องเขียนลูปเองทุกครั้ง','เลือกงานที่ยังค้างและรวมจำนวนเพื่อทำรายงาน','fn main() { let counts = [0, 2, 5]; let active: Vec<_> = counts.into_iter().filter(|n| *n > 0).collect(); println!("{:?}", active); }','[2, 5]\n','iterator adapter ส่วนมากยังไม่ทำงานจนมีตัวขับ เช่น collect, sum หรือ for');
add('fn/closures/closure_examples/iter_any','มีอย่างน้อยหนึ่งค่าหรือไม่ · any','Iterator::any รับ predicate และหยุดเมื่อพบค่าที่ให้ true; ถ้าไม่พบคืน false รวมถึง iterator ว่าง','ตรวจว่ามีโครงการใดงานค้างเกินเกณฑ์','fn main() { let pending = [1, 4, 2]; for limit in [3, 5] { println!("{}", pending.iter().any(|&n| n > limit)); } }','true\nfalse\n','predicate รับ Item ของ iterator ซึ่งอาจเป็น reference หากเริ่มจาก iter()');
add('fn/closures/closure_examples/iter_find','ค้นหาค่าแรก · find / position','find คืน Option ของ Item แรกที่ผ่าน predicate ส่วน position คืนตำแหน่ง; predicate ของ find ยืม Item จึงอาจเห็น reference ซ้อน','หาโครงการแรกที่มีงานค้างมากกว่าจำนวนที่กำหนด','fn main() { let counts = [1, 4, 8]; for limit in [3, 9] { println!("{:?}", counts.iter().find(|&&n| n > limit)); } println!("{:?}", counts.iter().position(|&n| n > 3)); }','Some(4)\nNone\nSome(1)\n','แยกให้ชัดว่าต้องการค่าหรือตำแหน่ง และดูชนิด Item ของ iterator ก่อนแก้จำนวน &');
add('fn/hof','ประกอบการแปลงข้อมูล · Higher Order Functions','ฟังก์ชันที่รับหรือคืนฟังก์ชันเรียกว่า higher order function; map/filter เปลี่ยนหรือคัดข้อมูลแบบ lazy ก่อนรวมผล','รวมเวลาของงานที่ใช้เวลาตั้งแต่เกณฑ์ขึ้นไป','fn main() { let minutes = [5, 15, 30]; for limit in [10, 20] { let total: u32 = minutes.iter().copied().filter(|n| *n >= limit).sum(); println!("{total}"); } }','45\n30\n','ลำดับ filter กับ map มีผลต่อทั้งความหมายและจำนวนงานที่ต้องทำ');
add('fn/diverging','ฟังก์ชันที่ไม่กลับมา · Diverging functions','ผลลัพธ์ ! หมายถึงไม่คืนการควบคุมตามปกติ เช่น panic หรือวนไม่จบ ต่างจาก () ที่คืนได้แต่ไม่มีข้อมูล','ตัวอย่างนี้เป็นการหยุดเมื่อ invariant ภายในพัง ไม่ใช่วิธีรับมือ input ผิดจากผู้ใช้','fn broken_state() -> ! { panic!("task invariant broken") }\nfn main() { broken_state(); }','','ใช้ Result สำหรับความผิดพลาดที่ผู้เรียกควรจัดการได้','should_panic','คาดว่าจะ panic ด้วยข้อความ task invariant broken');
add('mod','จัดขอบเขตโค้ด · Modules','module รวม function, struct, trait, impl และ module ย่อย โดยมีการควบคุม visibility ตามลำดับชั้น','แยกส่วนคำนวณรายงานออกจากจุดเริ่มโปรแกรม','mod report { pub fn pending(done: u32) -> u32 { 5 - done } }\nfn main() { println!("{}", report::pending(1)); println!("{}", report::pending(5)); }','4\n0\n','module ช่วยจัดชื่อและ visibility ไม่ได้แยกหน่วยคอมไพล์เป็น crate ใหม่');
add('mod/visibility','เปิดให้ใช้เท่าที่จำเป็น · Visibility','item ภายใน module เป็น private โดยปริยาย; pub เปิดการเข้าถึง และ pub(crate), pub(super), pub(in path) จำกัดขอบเขตได้','ให้ผู้เรียกใช้ API รายงาน ขณะที่ซ่อน helper ภายใน','mod report { fn limit() -> u32 { 10 } pub fn capped(n: u32) -> u32 { n.min(limit()) } }\nfn main() { println!("{} {}", report::capped(3), report::capped(20)); }','3 10\n','pub function ภายใน private module ยังถูกจำกัดด้วยทางเข้าของ module');
add('mod/struct_visibility','เปิด struct แต่ซ่อน field','visibility ของ struct กับ field แยกกัน; struct ที่มี private field ต้องสร้างผ่านฟังก์ชันที่เข้าถึง field ได้','บังคับให้ค่าจำนวนงานผ่าน constructor แทนการสร้าง field จากภายนอก','mod model { pub struct Count { value: u32 } impl Count { pub fn new(value: u32) -> Self { Self { value } } pub fn value(&self) -> u32 { self.value } } }\nfn main() { println!("{} {}", model::Count::new(2).value(), model::Count::new(8).value()); }','2 8\n','constructor เป็นจุดวาง validation เมื่อชนิดมีข้อจำกัดเพิ่มเติม');
add('mod/use','นำชื่อเข้ามาใน scope · use','use ย่อเส้นทางชื่อและใช้ as เปลี่ยนชื่อที่นำเข้าได้ โดยไม่เปลี่ยน visibility ของ item ต้นทาง','ตั้งชื่อ alias ให้คอลเลกชันที่ใช้เก็บจำนวนงาน','use std::collections::HashMap as Counts;\nfn main() { let mut counts = Counts::new(); counts.insert("work", 2); println!("{:?}", counts.get("work")); println!("{:?}", counts.get("home")); }','Some(2)\nNone\n','pub use ใช้เปิดชื่อจากอีก module เป็น API ของ module ปัจจุบันได้');
add('mod/super','อ้างตำแหน่งใน module · super / self','self อ้าง module ปัจจุบัน ส่วน super อ้าง parent module และ crate อ้างราก crate','module ย่อยใช้ค่าเกณฑ์ของ module รายงานแม่','mod report { const LIMIT: u32 = 3; pub mod status { pub fn busy(n: u32) -> bool { n > super::LIMIT } } }\nfn main() { println!("{} {}", report::status::busy(2), report::status::busy(5)); }','false true\n','ใช้เส้นทางที่สื่อความสัมพันธ์ระหว่าง module ให้ชัด');
add('mod/split','แยก module เป็นไฟล์ · File hierarchy','mod report; ให้ compiler หา report.rs หรือ report/mod.rs ตามโครงสร้าง module; ไม่ใช่การ include ข้อความตามอำเภอใจ','แยกตรรกะนับงานจาก main เมื่อไฟล์เริ่มยาว','// src/main.rs\nmod report;\nfn main() { println!("{}", report::pending(5, 2)); }\n\n// src/report.rs\npub fn pending(total: u32, done: u32) -> u32 { total - done }','3\n','เลือก layout ไฟล์แบบเดียวให้สม่ำเสมอในโครงการ','text','โค้ดสองไฟล์ ต้องสร้างโครงการ Cargo และแยกตามชื่อไฟล์ก่อนรัน cargo run');
add('crates','หน่วยคอมไพล์ · Crates','crate เป็นหน่วยคอมไพล์ อาจสร้าง executable หรือ library; module หลายตัวอยู่ใน crate เดียวกันได้','แยกโค้ดรายงานที่หลายโปรแกรมใช้ร่วมกันเป็น library','// library crate: src/lib.rs\npub fn pending(total: u32, done: u32) -> u32 { total - done }\n// caller example\n// pending(5, 2) == 3; pending(5, 5) == 0;','','แยก crate เมื่อขอบเขตการนำกลับไปใช้ต้องการ ไม่ใช่แค่เพราะไฟล์เริ่มยาว','text','ตัวอย่าง layout ของ library ไม่ใช่ executable เดี่ยว ต้องเรียก API จาก binary หรือ test');
add('crates/lib','สร้าง library · Creating a Library','library crate เปิด item ด้วย pub และไม่มี main ที่จำเป็นสำหรับ executable; rustc เลือกชนิด output ด้วย --crate-type=lib ได้','เก็บฟังก์ชันรายงานไว้ใน lib.rs เพื่อให้ CLI เรียกซ้ำ','// src/lib.rs\npub fn pending(total: u32, done: u32) -> u32 {\n    total - done\n}\n// สร้างด้วย cargo build ในโครงการ library','','pub เปิด API ให้ crate อื่น แต่ module ทางเข้าต้องเปิดถึง item ด้วย','text','สร้างโครงการด้วย cargo new task_core --lib และวางโค้ดใน src/lib.rs');
add('crates/using_lib','เรียก library · Using a Library','compiler ต้องทราบ library dependency; Cargo จัดการการ build และส่ง dependency ให้ rustc ส่วนการเรียก rustc ตรงใช้ --extern','binary ใช้ตรรกะจาก library ชื่อ task_core ผ่าน dependency แบบ path','# Cargo.toml ของ binary\n[dependencies]\ntask_core = { path = "../task_core" }\n\n# src/main.rs\n# fn main() { println!("{}", task_core::pending(5, 2)); }','3\n','เส้นทาง dependency อ้างจากโฟลเดอร์ที่เก็บ Cargo.toml','text','เป็นไฟล์ TOML กับแนวทางเรียก API ต้องมี library จากหัวข้อก่อนหน้า');
add('cargo','จัดการโครงการ · Cargo','Cargo ช่วยสร้าง build test และจัดการ dependency; Cargo.toml ระบุ package และ dependency ของโครงการ','เริ่มแอป CLI สำหรับงานแล้วใช้คำสั่งเดิมตลอดวงจรพัฒนา','cargo new task_app\ncd task_app\ncargo run\ncargo build\ncargo test','','cargo build สร้างไฟล์โปรแกรม ส่วน cargo run สร้างแล้วเรียกโปรแกรมด้วย','text','คำสั่ง shell ต้องติดตั้ง Rust/Cargo; output และเวลา build ขึ้นกับเครื่องและเวอร์ชัน');
add('cargo/deps','ระบุสิ่งที่แอปพึ่งพา · Dependencies','[dependencies] รองรับเวอร์ชันจาก registry, git และ path; Cargo.lock บันทึก resolution เพื่อให้ใช้ชุด dependency เดิมได้','หากย้ายตรรกะงานเป็น crate ในเครื่อง ใช้ path แทนการเผยแพร่ package ก่อน','[package]\nname = "task_app"\nversion = "0.1.0"\nedition = "2021"\n\n[dependencies]\ntask_core = { path = "../task_core" }','','ตรวจ API และรุ่นจริงของ dependency ก่อนนำตัวอย่างภายนอกมาวาง','text','TOML นี้ต้องมี crate task_core อยู่ใน path ที่ระบุ ไม่ใช่ dependency ที่ติดตั้งให้ในเว็บ');
add('cargo/conventions','โครงสร้างไฟล์ที่ Cargo รู้จัก · Conventions','src/main.rs เป็น binary หลัก src/lib.rs เป็น library; src/bin/ เก็บ binary เพิ่ม ส่วน tests/ examples/ benches/ มีบทบาทเฉพาะ','แอปเดียวมี CLI หลัก ตัวอย่างเรียก API และ integration tests แยกตำแหน่ง','task_app/\n  Cargo.toml\n  src/main.rs\n  src/lib.rs\n  src/bin/export.rs\n  tests/report.rs\n  examples/count.rs','','อย่าใส่ไฟล์ helper integration test เป็นไฟล์ .rs ระดับ tests โดยไม่ตั้งใจ เพราะ Cargo อาจมองเป็น test crate แยก','text','ผังไฟล์ ไม่ใช่โค้ด Rust ที่รันได้');
add('cargo/test','ให้ Cargo รันชุดตรวจ · Tests','cargo test คอมไพล์และรัน tests; #[test] ระบุฟังก์ชันทดสอบ การ assert ไม่ผ่านทำให้ test ล้มเหลว','ตรวจจำนวนงานค้างทั้งกรณีบางงานเสร็จและเสร็จทั้งหมด','// src/lib.rs\npub fn pending(total: u32, done: u32) -> u32 { total - done }\n#[test]\nfn counts_pending() {\n    assert_eq!(pending(5, 2), 3);\n    assert_eq!(pending(5, 5), 0);\n}','','เลือก test ที่ตรวจพฤติกรรมสำคัญและขอบเขตข้อมูล ไม่ใช่เพียงเรียกฟังก์ชันโดยไม่ assert','text','โค้ดสำหรับ src/lib.rs ต้องรันด้วย cargo test; rustc main แบบปกติไม่รัน #[test]');
add('cargo/build_scripts','ทำงานก่อนคอมไพล์ · Build scripts','build.rs เป็นโปรแกรม build script แยกต่างหากสำหรับงานอย่าง generate code หรือเชื่อม native library และสื่อสารกับ Cargo ผ่าน stdout ตามรูปแบบที่กำหนด','เมื่อไฟล์ตั้งค่าต้นแบบเปลี่ยน ให้ Cargo รู้ว่าควรรันขั้นตอน build ใหม่','// build.rs\nfn main() {\n    println!("cargo:rerun-if-changed=config.template");\n}','','build script ทำงานบน host; ถ้า cross compile อย่าสมมติว่า host คือ target','text','วางในราก package และเรียกผ่าน cargo build ไม่ใช่โค้ด runtime ของแอป');
add('attribute','ข้อมูลกำกับโค้ด · Attributes','#[...] ใช้กับ item ที่ตามมา ส่วน #![...] ใช้กับ enclosing item; attribute ควบคุม derive, lint, test และ conditional compilation ได้','สร้าง Debug ให้ข้อมูลรายงานโดยไม่ต้องเขียน implementation เอง','#[derive(Debug)]\nstruct Report { count: u32 }\nfn main() { println!("{:?}", Report { count: 2 }); println!("{:?}", Report { count: 5 }); }','Report { count: 2 }\nReport { count: 5 }\n','attribute ไม่ใช่คอมเมนต์ มันมีผลกับการคอมไพล์หรือเครื่องมือที่อ่านโค้ด');
add('attribute/unused','คำเตือนโค้ดที่ไม่ได้ใช้ · dead_code','dead_code lint แจ้ง item ที่ไม่ถูกใช้; #[allow(dead_code)] ปิดคำเตือนเฉพาะ scope ที่วาง attribute','helper ที่เก็บไว้เพื่อสาธิตอาจถูกปิด warning แต่แอปจริงควรถามก่อนว่ายังต้องมีหรือไม่','#[allow(dead_code)]\nfn old_report() {}\nfn report(n: u32) { println!("{n}"); }\nfn main() { report(2); report(5); }','2\n5\n','ปิด lint ในขอบเขตเล็กที่สุดและลบโค้ดที่ไม่จำเป็นแทนการปิด warning ทั้ง crate');
add('attribute/crate','กำกับ crate · crate attributes','crate_name และ crate_type ระบุชื่อและชนิดเมื่อเรียก rustc โดยตรง; โครงการ Cargo ให้กำหนดผ่าน manifest แทน','ทำ library คำนวณงานโดยใช้ rustc ตรงเพื่อเห็นหน่วย build','// task_core.rs\n#![crate_type = "lib"]\n#![crate_name = "task_core"]\npub fn pending(total: u32, done: u32) -> u32 { total - done }\n// rustc task_core.rs','','สำหรับแอปที่ใช้ Cargo ให้จัดการ package/library target ใน Cargo.toml','text','ไฟล์ library ต้อง build ด้วย rustc หรือ Cargo ไม่ใช่ executable ที่พิมพ์ output');
add('attribute/cfg','เลือกโค้ดตอนคอมไพล์ · cfg','#[cfg(...)] ตัด item ออกจากการคอมไพล์ ส่วน cfg!(...) ให้ bool และไม่ได้ตัดโค้ดในแขนง if ออกก่อนตรวจชนิด','เลือก separator ตามระบบปฏิบัติการโดยไม่สมมติว่าเครื่องผู้ใช้เหมือนเครื่องพัฒนา','fn main() { println!("windows={}", cfg!(target_os = "windows")); println!("unix={}", cfg!(unix)); }','','ทั้งสองแขนงของ if cfg!(...) ต้องเป็นโค้ดที่ถูกต้องบน target นั้น','text','ผลขึ้นกับ target ที่คอมไพล์ ไม่ใช่ค่าที่เปลี่ยนได้ขณะรัน');
add('attribute/cfg/custom','เพิ่มเงื่อนไข cfg ของตนเอง','rustc รับ custom cfg ผ่าน --cfg; item ที่ถูกตัดออกไม่สามารถอ้างถึงโดยไม่มีเงื่อนไขรองรับได้','ทำโหมดรายงานพิเศษที่เลือกในขั้นตอน build','#[cfg(compact)]\nfn limit() -> u32 { 5 }\n#[cfg(not(compact))]\nfn limit() -> u32 { 20 }\nfn main() { println!("{}", limit()); }','ไม่ส่ง --cfg compact: 20\nส่ง --cfg compact: 5','เมื่อใช้ Cargo ต้องประกาศ custom cfg ที่คาดไว้ให้ระบบตรวจ cfg ด้วย','text','รัน rustc main.rs และ rustc --cfg compact main.rs เพื่อเปรียบเทียบ ต้องมี compiler');
add('generics','โค้ดเดียวใช้หลายชนิด · Generics','type parameter เช่น T ให้โครงสร้างหรือฟังก์ชันทำงานกับชนิดหลายแบบ แต่ body ใช้ได้เฉพาะความสามารถที่มี bound รองรับ','หุ้มผลรายงานทั้งจำนวนงานและชื่อโครงการด้วยโครงสร้างเดียว','struct Report<T> { value: T }\nfn main() { let count = Report { value: 3 }; let name = Report { value: "work" }; println!("{} {}", count.value, name.value); }','3 work\n','เพิ่ม generic เมื่อมีชนิดหลายแบบจริง ไม่จำเป็นต้องทำทุก struct ให้เป็น generic');
add('generics/gen_fn','ฟังก์ชัน generic','ประกาศ fn name<T> ทำให้ T เป็น parameter ชนิด; ใช้ ::<Type> เมื่อ compiler อนุมานไม่พอ','คืนค่าที่เลือกไว้โดยไม่ผูกกับชนิดข้อมูลรายงาน','fn chosen<T>(value: T) -> T { value }\nfn main() { println!("{}", chosen::<u32>(3)); println!("{}", chosen("work")); }','3\nwork\n','body ที่รับ T ทั่วไปยังพิมพ์ด้วย {} ไม่ได้หากไม่มี Display bound');
add('generics/impl','method ของชนิด generic','impl<T> Report<T> สร้าง implementation สำหรับทุก T; impl Report<u32> สร้างเฉพาะชนิดนั้น','ให้รายงานอ่านค่าได้โดยยืม ไม่ต้อง clone ค่าทั้งชุด','struct Report<T>(T);\nimpl<T> Report<T> { fn value(&self) -> &T { &self.0 } }\nfn main() { println!("{}", Report(3).value()); println!("{}", Report("work").value()); }','3\nwork\n','อย่าลืมประกาศ <T> หลัง impl เมื่อ T ยังเป็น parameter');
add('generics/gen_trait','trait ที่มี type parameter','trait อาจ generic เหนือชนิด input ได้ และชนิดเดียวอาจมี implementation สำหรับ input หลายชนิดตามกฎ coherence','กำหนดวิธีตรวจข้อมูลของ task importer โดยรับ input เป็นชนิดที่กำหนด','trait Accepts<T> { fn accepts(&self, value: T) -> bool; }\nstruct Positive;\nimpl Accepts<u32> for Positive { fn accepts(&self, value: u32) -> bool { value > 0 } }\nfn main() { println!("{} {}", Positive.accepts(0), Positive.accepts(3)); }','false true\n','พิจารณา associated type เมื่อชนิดนั้นควรเลือกได้เพียงแบบเดียวต่อ implementation');
add('generics/bounds','ระบุความสามารถที่ต้องมี · Bounds','T: Trait จำกัดว่าผู้เรียกต้องส่งชนิดที่ implement trait นั้น จึงเรียก method ของ trait ใน body ได้','ฟังก์ชันพิมพ์รายงานต้องการ Display ไม่ได้ต้องการชนิดตัวเลขเฉพาะ','use std::fmt::Display;\nfn report<T: Display>(value: T) { println!("{value}"); }\nfn main() { report(3); report("work"); }','3\nwork\n','bound มีหน้าที่บอกความสามารถขั้นต่ำที่ body ต้องใช้');
add('generics/bounds/testcase_empty','trait ที่ใช้เป็นเครื่องหมาย · Empty bounds','trait ที่ไม่มี method ยังใช้เป็น bound เพื่อจำกัดกลุ่มชนิดได้','อนุญาตให้ส่งออกเฉพาะชนิดรายงานที่ประกาศว่า export ได้','trait Exportable {}\nstruct Report(u32);\nimpl Exportable for Report {}\nfn export<T: Exportable>(_: &T) { println!("export allowed"); }\nfn main() { export(&Report(2)); export(&Report(5)); }','export allowed\nexport allowed\n','marker trait บอกการจัดประเภทตามสัญญาของแอป แต่ไม่ได้ตรวจเนื้อหาข้อมูลให้เอง');
add('generics/multi_bounds','ต้องมีหลายความสามารถ · Multiple bounds','ใช้ + รวม trait bounds เช่น Display + Debug เมื่อฟังก์ชันต้องใช้ทั้งสองจริง','รายงานหนึ่งค่าในรูปแบบผู้ใช้และรูปแบบตรวจข้อมูล','use std::fmt::{Display, Debug};\nfn show<T: Display + Debug>(value: T) { println!("{value} / {value:?}"); }\nfn main() { show(3); show("work"); }','3 / 3\nwork / "work"\n','อย่าเพิ่ม Clone หรือ Debug เพียงเผื่อใช้ถ้า body ไม่ได้ต้องการ');
add('generics/where','ย้าย bound ให้อ่านง่าย · where','where แยกข้อจำกัดชนิดออกจากรายการ parameter และเขียนข้อจำกัดของชนิดประกอบได้','แยก signature รายงานออกจากข้อกำหนดการพิมพ์','fn report<T>(value: T)\nwhere T: std::fmt::Display {\n    println!("{value}");\n}\nfn main() { report(3); report("ready"); }','3\nready\n','ใช้ where เมื่อหลาย bound ทำให้ signature ยาวจนอ่านไม่ออก');
add('generics/new_types','แยกชนิดแม้ใช้ตัวเลขเหมือนกัน · Newtype','tuple struct สร้างชนิดใหม่ ต่างจาก type alias; compiler ไม่ถือว่า wrapper กับค่าภายในเป็นชนิดเดียวกัน','แยก TaskId ออกจาก UserId เพื่อกันส่งเลขสลับตำแหน่ง','struct TaskId(u32);\nstruct UserId(u32);\nfn main() { let task = TaskId(3); let user = UserId(3); println!("task={} user={}", task.0, user.0); }','task=3 user=3\n','การแยกชนิดช่วยกันสลับบทบาท แต่ยังต้องตรวจว่ารหัสนั้นมีอยู่จริง');
add('generics/assoc_items','ชนิดและค่าที่ผูกกับ trait · Associated items','associated item เป็นชื่อที่กำหนดใน trait หรือ impl เช่น associated type เพื่อบอกชนิดผลลัพธ์ของ implementation','แหล่งข้อมูลแต่ละชนิดระบุชนิดรายการที่มันคืน','trait Source { type Item; fn first(&self) -> Self::Item; }\nstruct Tasks;\nimpl Source for Tasks { type Item = u32; fn first(&self) -> u32 { 7 } }\nfn main() { println!("{}", Tasks.first()); }','7\n','ชนิดที่ผูกกับ trait ทำให้ signature ผู้ใช้ไม่ต้องรับ generic parameter ที่สัมพันธ์กันหลายตัว');
add('generics/assoc_items/the_problem','ปัญหา parameter ที่ต้องส่งต่อหลายชั้น','trait generic หลาย parameter อาจทำให้ผู้เรียกต้องระบุชนิดที่มีความสัมพันธ์กับ container ซ้ำในทุกฟังก์ชัน','แม้ฟังก์ชันต้องการเพียงจำนวนรายการ ก็ยังต้องนำ parameter ของ trait ไปด้วย','trait Contains<T> { fn has(&self, item: T) -> bool; }\nimpl Contains<u32> for Vec<u32> { fn has(&self, item: u32) -> bool { self.contains(&item) } }\nfn check<C: Contains<u32>>(c: &C, id: u32) -> bool { c.has(id) }\nfn main() { println!("{} {}", check(&vec![2, 5], 2), check(&vec![2, 5], 9)); }','true false\n','ถ้าชนิดสมาชิกถูกกำหนดโดย container อยู่แล้ว associated type อาจสื่อความสัมพันธ์ได้ตรงกว่า');
add('generics/assoc_items/types','ให้ implementation เลือกชนิด · Associated types','ประกาศ type Item ใน trait แล้วระบุใน impl; ผู้เรียกอ้างชนิดผ่าน C::Item แทน parameter แยก','collection งานประกาศชนิดรหัสของสมาชิกใน API','trait Contains { type Item; fn has(&self, item: Self::Item) -> bool; }\nimpl Contains for Vec<u32> { type Item = u32; fn has(&self, item: u32) -> bool { self.contains(&item) } }\nfn main() { println!("{} {}", vec![2, 5].has(2), vec![2, 5].has(9)); }','true false\n','trait ที่มี associated type เลือกค่า type นั้นต่อ implementation เดียว ไม่เหมือน generic input หลายแบบ');
add('generics/phantom','บอกชนิดที่ไม่ได้เก็บจริง · PhantomData','PhantomData<T> ทำให้ compiler รับรู้ความสัมพันธ์กับ T แม้ไม่มี field ข้อมูล T จริง และมีผลต่อการตรวจชนิดและคุณสมบัติของ wrapper','ทำรหัสงานคนละหมวดโดยไม่ต้องเก็บข้อมูล marker เพิ่ม','use std::marker::PhantomData;\nstruct Id<T> { value: u32, marker: PhantomData<T> }\nstruct Task;\nfn main() { for value in [2, 5] { let id = Id::<Task> { value, marker: PhantomData }; println!("{}", id.value); } }','2\n5\n','PhantomData ไม่ทำ validation ให้ และความสัมพันธ์แบบ ownership/variance ต้องออกแบบอย่างระมัดระวัง');
add('generics/phantom/testcase_units','กันการบวกคนละหน่วย · Phantom units','ใช้ marker แยก Length<Meters> ออกจาก Length<Millimeters> ได้ และกำหนด Add เฉพาะหน่วยเดียวกัน','ข้อมูลระยะทางจากสองเซนเซอร์รวมได้เมื่อหน่วยตรงกัน','use std::{marker::PhantomData, ops::Add};\nstruct Meters;\nstruct Length<U>(u32, PhantomData<U>);\nimpl<U> Add for Length<U> { type Output = Self; fn add(self, rhs: Self) -> Self { Self(self.0 + rhs.0, PhantomData) } }\nfn main() { let a = Length::<Meters>(2, PhantomData); let b = Length::<Meters>(5, PhantomData); println!("{}", (a + b).0); }','7\n','การแปลงหน่วยต้องกำหนดสูตรเอง marker เพียงกันการผสมชนิดที่ไม่ตรงกัน');

process.on('exit', () => build(rows));
add('scope','ขอบเขตข้อมูล · Scoping rules','scope เกี่ยวข้องกับการสร้างและทำลายค่า ส่วน ownership, borrowing และ lifetime ช่วยกำหนดว่าค่าใดใช้ที่ใดได้อย่างปลอดภัย','ข้อมูลที่ยืมมาเพื่อรายงานต้องไม่อยู่ยาวกว่าเจ้าของข้อมูล','fn main() { let tasks = vec!["backup", "review"]; { let summary = &tasks; println!("{}", summary.len()); } println!("{}", tasks.len()); }','2\n2\n','แยกอายุของข้อมูลออกจากระยะที่มีการยืมข้อมูลนั้น');
add('scope/raii','คืนทรัพยากรเมื่อจบขอบเขต · RAII','ค่าที่เป็นเจ้าของทรัพยากรเรียก Drop เมื่อถูกทำลาย จึงผูกการคืนทรัพยากรกับอายุของค่าได้โดยไม่ต้องสั่ง free เอง','ดูว่าทรัพยากรจำลองของงานย่อยถูกคืนก่อนจบ main','struct Work(&\'static str);\nimpl Drop for Work { fn drop(&mut self) { println!("release {}", self.0); } }\nfn main() { let _outer = Work("outer"); { let _inner = Work("inner"); println!("working"); } println!("finished"); }','working\nrelease inner\nfinished\nrelease outer\n','Drop ไม่รับประกันว่าจะถูกเรียกหาก process abort หรือถูกระบบหยุดทันที');
add('scope/move','ส่งต่อเจ้าของค่า · Ownership and moves','assignment และการส่ง argument แบบค่าอาจย้าย ownership สำหรับชนิดที่ไม่ใช่ Copy หลัง move ใช้ binding เดิมไม่ได้จนกว่าจะกำหนดค่าใหม่','ส่งชื่องานจากขั้นตอนอ่านไปขั้นตอนบันทึกโดยไม่คัดลอก String','fn save(name: String) { println!("saved {name}"); }\nfn main() { let draft = String::from("backup"); let ready = draft; save(ready); let count = 3_u32; let copied = count; println!("{count} {copied}"); }','saved backup\n3 3\n','ใช้การยืมเมื่อผู้รับเพียงอ่านข้อมูลและไม่จำเป็นต้องเป็นเจ้าของ');
add('scope/move/mut','เจ้าของใหม่เลือก mut ได้','mutability ของ binding ไม่ได้ผูกติดกับค่าตลอดไป ค่าจาก binding immutable ย้ายไป binding mutable ได้','รับรายการงานที่อ่านมา แล้วเริ่มขั้นตอนแก้ไขภายใต้เจ้าของใหม่','fn main() { let loaded = vec![1, 2]; let mut editable = loaded; editable.push(3); println!("{:?}", editable); }','[1, 2, 3]\n','การเปลี่ยนชื่อ binding หลัง move ไม่ได้ clone buffer');
add('scope/move/partial_move','ย้ายเพียงบาง field · Partial moves','destructuring ย้าย field ที่ไม่ใช่ Copy บางส่วนพร้อมยืม field อื่นได้ หลังจากนั้นใช้ทั้ง struct เดิมไม่ได้ แต่ field ที่ยังไม่ถูกย้ายอาจใช้ได้; ชนิดที่มี Drop มีข้อจำกัดเพิ่ม','ส่ง title ไปเก็บแยก แต่ยังอ่านเลขความสำคัญของงานได้','struct Task { title: String, priority: u8 }\nfn main() { let task = Task { title: "backup".into(), priority: 2 }; let Task { title, .. } = task; println!("{title} {}", task.priority); }','backup 2\n','ระวัง move ที่เกิดจาก pattern โดยไม่ได้ตั้งใจ ถ้าต้องแค่อ่านให้ยืม field');
add('scope/borrow','ใช้ข้อมูลโดยไม่รับ ownership · Borrowing','&T ให้ผู้เรียกยืมอ่านข้อมูล โดยเจ้าของยังมีหน้าที่ทำลายค่า; reference ต้องไม่อยู่เลยอายุข้อมูลที่อ้างถึง','รายงานชื่องานโดยไม่กิน String ที่ผู้เรียกยังต้องใช้ต่อ','fn show(title: &str) { println!("{title}"); }\nfn main() { let title = String::from("backup"); show(&title); show(&title); println!("length={}", title.len()); }','backup\nbackup\nlength=6\n','รับ &str แทน &String เมื่อฟังก์ชันต้องการเพียงอ่านข้อความ');
add('scope/borrow/mut','ให้ยืมแก้ข้อมูล · &mut','&mut T ให้สิทธิ์แก้ข้อมูลที่ยืมมา โดยเจ้าของเดิมต้องอนุญาตให้ยืมแบบ mutable','ฟังก์ชันปิดงานแก้จำนวนงานค้างผ่าน reference','fn finish(pending: &mut u32) { if *pending > 0 { *pending -= 1; } }\nfn main() { let mut pending = 2; finish(&mut pending); println!("{pending}"); finish(&mut pending); println!("{pending}"); }','1\n0\n','ใช้ * เมื่อแก้ค่าที่อยู่หลัง reference ไม่ใช่เปลี่ยนตัว reference เอง');
add('scope/borrow/alias','กฎการยืมที่ทับซ้อน · Aliasing','ขณะมี shared borrow ที่ยังใช้งานอยู่จะสร้าง mutable borrow ทับไม่ได้; mutable borrow ต้องไม่มีการเข้าถึงที่ขัดกันระหว่างที่มันยังใช้ต่อ','อ่านรายการจากสองจุด แล้วค่อยเพิ่มงานเมื่อการอ่านครั้งสุดท้ายจบ','fn main() { let mut ids = vec![1]; let a = &ids; let b = &ids; println!("{} {}", a.len(), b.len()); ids.push(2); println!("{}", ids.len()); }','1 1\n2\n','compiler มักจบการยืมหลังการใช้ครั้งสุดท้าย ไม่จำเป็นต้องรอปิดบล็อกเสมอ');
add('scope/borrow/ref','ยืม field ผ่าน pattern · ref','ref และ ref mut สร้าง binding เป็น reference ระหว่าง destructuring โดยไม่ย้าย field ออกจากเจ้าของ','อ่าน title ของงานผ่าน pattern แล้วใช้ทั้งงานต่อได้','struct Task { title: String }\nfn main() { let task = Task { title: "backup".into() }; let Task { ref title } = task; println!("{title}"); println!("{}", task.title); }','backup\nbackup\n','ใน Rust รุ่นปัจจุบัน match ergonomics ช่วยยืมผ่าน pattern ได้หลายกรณี โดยยังต้องเข้าใจกฎ ownership');
add('scope/lifetime','อายุของการยืม · Lifetimes','lifetime ใช้อธิบายช่วงที่ reference ใช้ได้ compiler ตรวจว่าข้อมูลที่อ้างถึงยังอยู่; annotation ไม่ได้ยืดอายุข้อมูลหรือสร้างข้อมูลใหม่','ฟังก์ชันเลือกชื่อรายงานคืน reference ที่ยืมมาจาก input','fn choose<\'a>(a: &\'a str, b: &\'a str) -> &\'a str { if a.len() >= b.len() { a } else { b } }\nfn main() { println!("{}", choose("work", "home")); println!("{}", choose("work", "personal")); }','work\npersonal\n','เมื่อคืนค่าจากข้อมูลที่สร้างในฟังก์ชันเอง ให้คืนค่าที่เป็นเจ้าของ เช่น String');
add('scope/lifetime/explicit','ระบุความสัมพันธ์ของ reference','ชื่ออย่าง \'a ใน signature บอกความสัมพันธ์ระหว่างอายุ reference โดยไม่ได้กำหนดจำนวนวินาทีหรือบังคับให้ข้อมูลอยู่ตลอดโปรแกรม','เลือกชื่อที่ยาวกว่าโดยให้ผลลัพธ์ใช้ได้เท่าช่วงร่วมที่ input ทั้งสองยังถูกต้อง','fn longer<\'a>(a: &\'a str, b: &\'a str) -> &\'a str { if a.len() > b.len() { a } else { b } }\nfn main() { let work = String::from("work"); let personal = String::from("personal"); println!("{}", longer(&work, &personal)); }','personal\n','ตัวอักษรชื่อ lifetime ไม่มีความหมายพิเศษ แต่ความสัมพันธ์ที่ประกาศมีความหมาย');
add('scope/lifetime/fn','lifetime ใน signature ฟังก์ชัน','reference ที่คืนต้องผูกอายุกับ reference ที่รับเข้า หรือข้อมูลที่มีอายุเพียงพออย่าง static; คืน reference ไปยัง local ที่กำลังถูกทำลายไม่ได้','คืนส่วนชื่อที่ตัดช่องว่างโดยไม่จอง String ใหม่','fn clean<\'a>(title: &\'a str) -> &\'a str { title.trim() }\nfn main() { println!("[{}]", clean(" work ")); println!("[{}]", clean("home")); }','[work]\n[home]\n','annotation ทำให้ความสัมพันธ์เห็นชัด แต่ตัวอย่าง input reference เดียวมักละได้ด้วย elision');
add('scope/lifetime/methods','lifetime ใน method','method ใช้ lifetime เช่นเดียวกับฟังก์ชัน และ receiver &self มักให้กฎ elision ผูกผลลัพธ์ reference กับ self ได้','คืนชื่องานที่ยืมจาก field ของตัวเอง','struct Task(String);\nimpl Task { fn title<\'a>(&\'a self) -> &\'a str { &self.0 } }\nfn main() { let task = Task("backup".into()); println!("{}", task.title()); }','backup\n','อย่าใส่ lifetime ที่ยาวเกินจำเป็นให้ &mut self เพราะอาจจำกัดการใช้ instance ต่อ');
add('scope/lifetime/struct','struct ที่ยืมข้อมูล','เมื่อ struct เก็บ reference ที่อายุขึ้นกับข้อมูลภายนอก ใช้ lifetime parameter บอกความสัมพันธ์นั้น; field ที่ใช้ static โดยตรงไม่ต้องมี parameter','สร้างมุมมองรายงานชั่วคราวที่ยืมชื่อโครงการโดยไม่ clone','struct View<\'a> { title: &\'a str }\nfn main() { let title = String::from("work"); let view = View { title: &title }; println!("{}", view.title); println!("{}", title); }','work\nwork\n','ถ้า instance ต้องอยู่ต่อหลัง input ถูกทิ้ง ให้เก็บ String หรือรูปแบบ ownership ที่เหมาะสม');
add('scope/lifetime/trait','lifetime ใน trait implementation','ชนิดที่มี lifetime parameter ต้องประกาศ parameter ที่ impl ด้วยเมื่อ implementation ใช้ได้กับหลายอายุการยืม','ทำ Display ให้มุมมองชื่องานที่ยืมมาจากข้อมูลอื่น','use std::fmt;\nstruct View<\'a>(&\'a str);\nimpl<\'a> fmt::Display for View<\'a> { fn fmt(&self, f: &mut fmt::Formatter<\'_>) -> fmt::Result { write!(f, "{}", self.0) } }\nfn main() { println!("{} {}", View("work"), View("home")); }','work home\n','แยก lifetime ของข้อมูลที่ struct ยืมออกจาก lifetime ของการยืม self ใน method');
add('scope/lifetime/lifetime_bounds','กำหนดอายุขั้นต่ำ · Lifetime bounds','T: \'a บอกว่า reference ภายใน T ต้องใช้ได้ตลอด \'a; \'a: \'b บอกว่า \'a อยู่ได้นานอย่างน้อยเท่า \'b','helper อ่านค่ารายงานที่ยืมได้ตลอดช่วงที่กำลังแสดงผล','fn show<\'a, T>(value: &\'a T) where T: std::fmt::Display + \'a { println!("{value}"); }\nfn main() { let title = String::from("work"); show(&title); show(&3); }','work\n3\n','lifetime bound ไม่ได้แปลว่าค่าต้องมี reference ภายในเสมอไป');
add('scope/lifetime/lifetime_coercion','ใช้ reference ในช่วงที่สั้นลง','reference ที่ใช้ได้นานกว่าสามารถใช้ในบริบทที่ต้องการอายุสั้นกว่าได้ตามกฎ subtyping; ไม่ใช่การยืดอายุค่าที่สั้นกว่า','รวมชื่อคงที่กับข้อมูลอ่านจากผู้ใช้ภายในช่วงที่ผู้ใช้ยังมีข้อมูลนั้น','fn pick<\'a>(a: &\'a str, b: &\'a str) -> &\'a str { if b.is_empty() { a } else { b } }\nfn main() { let input = String::from("home"); println!("{}", pick("default", &input)); println!("{}", pick("default", "")); }','home\ndefault\n','การย่ออายุ reference ใน signature ไม่ได้เปลี่ยนอายุจริงของเจ้าของ');
add('scope/lifetime/static_lifetime','ความหมายสองแบบของ static','&\'static T อ้างข้อมูลที่อยู่ได้ตลอดโปรแกรม ส่วน T: \'static หมายถึง T ไม่มี reference ที่ผูกกับข้อมูลอายุสั้นกว่า; String ที่เป็นเจ้าของจึงผ่าน bound ได้และยังถูก drop ปกติ','ส่งค่าที่เป็นเจ้าของให้ตัวประมวลผลที่ไม่ยืมข้อมูลจาก stack ของผู้เรียก','fn owned<T: std::fmt::Display + \'static>(value: T) { println!("{value}"); }\nfn main() { let name: &\'static str = "default"; owned(name); owned(String::from("work")); }','default\nwork\n','อย่าแก้ปัญหา borrow checker ด้วยการใส่ static ถ้าข้อมูลจริงไม่ได้มีอายุตามนั้น');
add('scope/lifetime/elision','ละ lifetime เมื่อกฎชัด · Elision','แต่ละ input reference ที่ละ annotation ได้ lifetime ของตนเอง; input เดียวเชื่อมกับ output และใน method ที่มี &self กฎเชื่อม output กับ receiver','API ตัดช่องว่างชื่ออ่านง่ายได้โดยไม่ต้องเขียนชื่อ lifetime เอง','fn clean(title: &str) -> &str { title.trim() }\nfn main() { println!("[{}]", clean(" work ")); println!("[{}]", clean(" home ")); }','[work]\n[home]\n','หากคืน reference และมี input หลายตัวที่กฎยังเลือกไม่ได้ ต้องประกาศความสัมพันธ์ให้ชัด');
add('trait','สัญญาพฤติกรรม · Traits','trait ประกาศ method ที่ชนิดต้องมี และอาจให้ default method ที่เรียก method อื่นใน trait; impl Trait for Type เลือกพฤติกรรมของชนิดนั้น','ให้ตัวส่งออกรายงานหลายแบบมี API เดียวกัน','trait Export { fn extension(&self) -> &str; fn name(&self) -> String { format!("report.{}", self.extension()) } }\nstruct Csv;\nimpl Export for Csv { fn extension(&self) -> &str { "csv" } }\nfn main() { println!("{}", Csv.name()); }','report.csv\n','แยก trait ตามพฤติกรรมที่ผู้เรียกต้องใช้ ไม่จำเป็นต้องมีหนึ่ง trait ต่อหนึ่ง struct');
add('trait/derive','ให้ compiler เขียน trait พื้นฐาน · Derive','derive สร้าง implementation เช่น Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash และ Default ตามความสามารถของ field; Display ต้องออกแบบเอง','เปรียบเทียบตัวกรองงานและพิมพ์ตรวจความแตกต่าง','#[derive(Debug, PartialEq, Clone)]\nstruct Filter { done: bool }\nfn main() { let a = Filter { done: false }; let b = a.clone(); println!("{}", a == b); println!("{}", a == Filter { done: true }); }','true\nfalse\n','derive Eq/Hash ด้วยกันสำหรับ key ที่เปรียบเทียบจาก field เดียวกัน');
add('trait/dyn','เลือก implementation ขณะรัน · dyn Trait','trait object ผ่าน pointer อย่าง Box<dyn Trait> เก็บค่าคนละชนิดภายใต้ interface เดียวได้ และ dispatch method ขณะรัน โดย trait ต้องรองรับ dyn','เลือกชนิดไฟล์ส่งออกจากค่าตั้งค่าโดยคืนตัวส่งออกผ่าน trait object','trait Export { fn extension(&self) -> &str; }\nstruct Csv; struct Text;\nimpl Export for Csv { fn extension(&self) -> &str { "csv" } }\nimpl Export for Text { fn extension(&self) -> &str { "txt" } }\nfn exporter(csv: bool) -> Box<dyn Export> { if csv { Box::new(Csv) } else { Box::new(Text) } }\nfn main() { println!("{} {}", exporter(true).extension(), exporter(false).extension()); }','csv txt\n','ใช้ dyn เมื่อต้องเก็บหรือคืนหลาย concrete types ผ่าน interface เดียวจริง');
add('trait/ops','กำหนดความหมาย operator · Operator overloading','operator หลายตัวเรียก trait ใน std::ops เช่น + ใช้ Add; associated type Output กำหนดชนิดผลลัพธ์','บวกเวลาประเมินงานที่ใช้หน่วยเดียวกัน','use std::ops::Add;\nstruct Minutes(u32);\nimpl Add for Minutes { type Output = Self; fn add(self, rhs: Self) -> Self { Self(self.0 + rhs.0) } }\nfn main() { println!("{}", (Minutes(15) + Minutes(30)).0); println!("{}", (Minutes(0) + Minutes(5)).0); }','45\n5\n','ความหมายของ operator ควรคาดเดาได้จากชนิด อย่าให้ + ทำงานที่ซ่อน side effect แปลกไป');
add('trait/drop','ทำงานตอนค่าถูกทำลาย · Drop','Drop::drop ถูกเรียกอัตโนมัติเมื่อค่าถูกทำลาย ใช้คืนทรัพยากร; ถ้าต้องการทำลายก่อน ใช้ std::mem::drop แทนเรียก method drop โดยตรง','ดูเวลาคืน resource จำลองของงานแต่ละชิ้น','struct Job(u32);\nimpl Drop for Job { fn drop(&mut self) { println!("close {}", self.0); } }\nfn main() { let first = Job(1); let _second = Job(2); drop(first); println!("continue"); }','close 1\ncontinue\nclose 2\n','Drop ไม่คืน Result หากขั้นตอนต้องรายงานข้อผิดพลาด ให้มี method ปิดงานแบบ explicit ด้วย');
add('trait/iter','สร้างลำดับข้อมูล · Iterator','Iterator ระบุ associated type Item และ next() -> Option<Item>; adapter เช่น take/map ทำงานบนสัญญานี้ได้','สร้างเลขงานจากตัวนับที่หมดแล้วคืน None','struct Ids { next: u32, end: u32 }\nimpl Iterator for Ids { type Item = u32; fn next(&mut self) -> Option<u32> { if self.next >= self.end { None } else { let id = self.next; self.next += 1; Some(id) } } }\nfn main() { for id in (Ids { next: 3, end: 5 }) { println!("{id}"); } }','3\n4\n','next เป็นตัวขับลำดับ ส่วน adapter อย่าง map ยังต้องมีผู้เรียกให้เดินหน้า');
add('trait/impl_trait','ซ่อนชนิด concrete · impl Trait','impl Trait ใน parameter คือการรับชนิดที่ผ่าน bound; ในตำแหน่ง return ซ่อน concrete type เดียวที่ compiler รู้ โดยไม่ใช่ trait object','คืน iterator ของงานที่ผ่านเกณฑ์โดยไม่เขียนชนิด adapter ที่ยาว','fn selected(limit: u32) -> impl Iterator<Item = u32> { (1..=5).filter(move |n| *n > limit) }\nfn main() { println!("{:?}", selected(3).collect::<Vec<_>>()); println!("{:?}", selected(5).collect::<Vec<_>>()); }','[4, 5]\n[]\n','return impl Trait ไม่อนุญาตให้แต่ละแขนงคืน concrete type คนละชนิดโดยอัตโนมัติ');
add('trait/clone','คัดลอกโดยตั้งใจ · Clone และ Copy','Clone ขอสำเนาแบบ explicit และอาจมีต้นทุน ส่วน Copy คัดลอกบิตแทน move โดยอัตโนมัติและไม่ใช้กับชนิดที่มี Drop; Clone ของ smart pointer บางชนิดแชร์ข้อมูลเดิม','แยกรายการงานสำรองแล้วแก้ต้นฉบับเพื่อเห็นว่า Vec clone แยก buffer','fn main() { let mut live = vec![1, 2]; let snapshot = live.clone(); live.push(3); println!("{:?}", live); println!("{:?}", snapshot); }','[1, 2, 3]\n[1, 2]\n','อย่าแก้ borrow error ด้วย clone โดยไม่เข้าใจว่าต้องการ ownership แยกจริงหรือไม่');
add('trait/supertraits','trait ที่ต้องมีอีก trait ก่อน · Supertraits','trait Child: Parent บังคับให้ชนิดที่ implement Child ต้อง implement Parent ด้วย; ไม่ใช่การสืบทอด field ของ class','สิ่งที่ส่งออกได้ต้องมีชื่อเพื่อให้รายงานใช้แสดงผล','trait Named { fn name(&self) -> &str; }\ntrait Exportable: Named { fn filename(&self) -> String { format!("{}.txt", self.name()) } }\nstruct Report;\nimpl Named for Report { fn name(&self) -> &str { "tasks" } }\nimpl Exportable for Report {}\nfn main() { println!("{}", Report.filename()); }','tasks.txt\n','ใช้ supertrait เมื่อพฤติกรรม child ต้องพึ่งสัญญาของ parent จริง');
add('trait/disambiguating','method ชื่อซ้ำกัน · Fully Qualified Syntax','ชนิดเดียว implement หลาย trait ที่มี method ชื่อเดียวกันได้ โดยเลือกเรียก Trait::method หรือ <Type as Trait>::method ให้ชัด','ชื่อรายงานที่ใช้แสดงกับชื่อที่ใช้ในไฟล์อาจมาจาก interface คนละชุด','trait DisplayName { fn name(&self) -> &str; }\ntrait FileName { fn name(&self) -> &str; }\nstruct Report;\nimpl DisplayName for Report { fn name(&self) -> &str { "Task report" } }\nimpl FileName for Report { fn name(&self) -> &str { "tasks.txt" } }\nfn main() { println!("{}", DisplayName::name(&Report)); println!("{}", <Report as FileName>::name(&Report)); }','Task report\ntasks.txt\n','ถ้าความหมายต่างกันมาก ชื่อ method ที่เฉพาะเจาะจงช่วยลดความกำกวมตั้งแต่ API');
add('macros','สร้างโค้ดจาก pattern · macro_rules!','macro_rules! จับ token pattern แล้วขยายเป็นโค้ดก่อนคอมไพล์ ใช้ ! ที่จุดเรียก ต่างจากฟังก์ชันที่รับค่าตอนรัน','ย่อรูปแบบพิมพ์เลขงานซ้ำโดยให้ compiler ตรวจโค้ดที่ขยายแล้ว','macro_rules! task_line { ($id:expr) => { println!("task={}", $id) }; }\nfn main() { task_line!(2); task_line!(3 + 2); }','task=2\ntask=5\n','ใช้ฟังก์ชันก่อนถ้ารูปแบบ input และ output ปกติพอ ไม่จำเป็นต้องมี macro ทุกจุดที่ซ้ำ');
add('macros/syntax','โครงสร้างของ macro','macro ประกอบด้วย matcher และ expansion แต่ละแขนงใช้ => เชื่อมกัน; fragment specifier ระบุชนิด token ส่วน repetition รับจำนวนส่วนซ้ำได้','สร้างบรรทัดสรุปที่รับ expression เป็นค่าของจำนวนงาน','macro_rules! count { ($n:expr) => { println!("count={}", $n) }; }\nfn main() { count!(0); count!(2 + 3); }','count=0\ncount=5\n','macro จับโครงสร้าง syntax ไม่ใช่การแทนข้อความด้วย string ธรรมดา');
add('macros/designators','บอกชนิด fragment · Designators','fragment เช่น ident, expr, ty, pat, stmt, block, item และ tt จำกัดว่าส่วนที่จับเป็นโครงสร้างแบบใด','สร้าง helper ที่มีชื่อจาก ident และค่าจาก expr','macro_rules! define_count { ($name:ident, $value:expr) => { fn $name() -> u32 { $value } }; }\ndefine_count!(pending, 2 + 3);\ndefine_count!(completed, 2);\nfn main() { println!("{} {}", pending(), completed()); }','5 2\n','เลือก fragment ให้ตรงสิ่งที่ macro ต้องรับ เพื่อให้ข้อผิดพลาดอ่านง่าย');
add('macros/overload','หลายรูปแบบการเรียก · Overload','macro มีหลาย matcher ได้ โดยเลือกแขนงที่ตรงตามลำดับ; รูปแบบ argument ไม่จำเป็นต้องเหมือนฟังก์ชัน','ให้ผู้เรียกเลือกรายงานค่าเดี่ยวหรือรวมสองค่า','macro_rules! report { ($a:expr) => { println!("{}", $a) }; ($a:expr, $b:expr) => { println!("{}", $a + $b) }; }\nfn main() { report!(2); report!(2, 5); }','2\n7\n','แขนงที่กว้างเกินไปก่อนแขนงเฉพาะอาจจับ token ไปก่อน');
add('macros/repeat','รับค่าซ้ำ · Repetition','$(...),* จับศูนย์ครั้งขึ้นไป ส่วน + อย่างน้อยหนึ่งครั้ง และระบุตัวคั่นอย่างจุลภาคได้','สรุปเวลางานจำนวนเท่าใดก็ได้จาก expression หลายตัว','macro_rules! total { ($($n:expr),*) => { 0_u32 $(+ $n)* }; }\nfn main() { println!("{}", total!()); println!("{}", total!(5, 15, 30)); }','0\n50\n','กำหนดพฤติกรรมกรณี input ว่างให้ชัดเมื่อเลือก *');
add('macros/dry','ลด boilerplate ด้วย macro · DRY','macro สามารถสร้าง function หรือชุดทดสอบที่มีโครงสร้างเหมือนกันได้ แต่โค้ดที่ซ้ำเพียงเล็กน้อยอาจอ่านง่ายกว่าการซ่อนรูปแบบ','สร้าง helper หลายชื่อที่ต่างกันเพียงเกณฑ์รายงาน','macro_rules! threshold { ($name:ident, $limit:expr) => { fn $name(n: u32) -> bool { n > $limit } }; }\nthreshold!(busy, 3);\nthreshold!(overloaded, 10);\nfn main() { println!("{} {}", busy(5), overloaded(5)); }','true false\n','ถ้าความต่างเป็นแค่ค่าที่ส่งเข้า ฟังก์ชันรับ limit มักง่ายกว่า macro นี้');
add('macros/dsl','รูปแบบภาษาเล็กในแอป · DSL','DSL ใน macro กำหนด token เฉพาะแล้วขยายเป็น Rust ปกติได้ แต่ยังอยู่ภายใต้กฎ matcher และชนิดของ Rust','เขียนรูปแบบสรุปจำนวนงานที่อ่านคล้ายคำสั่งรายงาน','macro_rules! summary { (pending $total:expr => $done:expr) => { $total - $done }; }\nfn main() { println!("{}", summary!(pending 5_u32 => 2)); println!("{}", summary!(pending 5_u32 => 5)); }','3\n0\n','DSL เพิ่ม syntax ที่ผู้ใช้ต้องเรียน ใช้เมื่อสื่อความหมายดีกว่า function call จริง');
add('macros/variadics','จำนวน argument ไม่คงที่ · Variadics','macro รองรับจำนวน argument เปลี่ยนได้ด้วย repetition หรือ recursion ต่างจาก function signature ทั่วไปที่มีจำนวน parameter คงที่','พิมพ์สรุปงานแต่ละโครงการจากรายการ expression หลายชุด','macro_rules! reports { ($($name:expr => $count:expr),+ $(,)?) => { $(println!("{}={}", $name, $count);)+ }; }\nfn main() { reports!("work" => 3, "home" => 0); }','work=3\nhome=0\n','ถ้าข้อมูลมาจาก runtime ให้ส่ง slice หรือ iterator แทน variadic macro');
add('error','ออกแบบทางผิดพลาด · Error handling','Option แทนค่าที่อาจไม่มี Result เก็บค่าหรือสาเหตุล้มเหลว ส่วน panic เหมาะกับสภาพที่ไม่ควรทำงานต่อในเส้นทางนั้น','ข้อมูลจำนวนงานจากผู้ใช้ควร parse เป็น Result แทนหยุดทั้งแอปทันที','fn main() { for raw in ["3", "oops"] { match raw.parse::<u32>() { Ok(n) => println!("tasks={n}"), Err(_) => println!("invalid count") } } }','tasks=3\ninvalid count\n','เลือก Error ที่ช่วยให้ผู้เรียกตัดสินใจว่าจะ retry แจ้งผู้ใช้ หรือหยุด');
add('error/panic','หยุดเมื่อเดินต่อไม่ได้ · panic!','panic! เริ่มการล้มเหลวของเส้นทางทำงาน โดยพฤติกรรม unwind หรือ abort ขึ้นกับ panic strategy และ runtime','ตัวอย่างจำลอง invariant ที่ไม่ยอมรับจำนวนงานติดลบ เพื่อให้เห็นจุดที่หยุดก่อนข้อความถัดไป','fn main() { println!("before"); panic!("negative task count"); }','before\n','สำหรับข้อมูลจากผู้ใช้ให้คืน Result พร้อมข้อผิดพลาดที่แก้ได้ แทน panic','should_panic','คาดว่า stderr มีข้อความ negative task count และโปรแกรมจบไม่สำเร็จ');
add('error/abort_unwind','สองวิธีจบเมื่อ panic · abort / unwind','unwind คลาย stack และทำลายค่าตามเส้นทางที่คลาย ส่วน abort หยุด process โดยไม่คลาย stack; cfg(panic = "...") แยกโค้ดตามกลยุทธ์ที่ build','ตรวจการตั้งค่า build ก่อนอาศัย Drop ของตัวจัดการงานเพื่อทำ cleanup','fn main() {\n    println!("unwind={}", cfg!(panic = "unwind"));\n    println!("abort={}", cfg!(panic = "abort"));\n}','','อย่าอาศัย Drop เป็นวิธีเดียวในการรับประกันการเขียนข้อมูลถาวรเมื่อ process อาจหยุดฉับพลัน','text','ผลขึ้นกับ build strategy เช่น rustc -C panic=abort หรือค่า profile ของ Cargo; ต้องทดสอบทั้งสอง build');
add('error/option_unwrap','ค่าอาจไม่มี · Option / unwrap','Option<T> มี Some(T) และ None; unwrap คืนค่าจาก Some แต่ panic เมื่อ None ขณะที่ expect เพิ่มข้อความอธิบายได้','เลขงานที่ผู้ใช้เลือกอาจไม่มี จัดการ None เป็นสถานะปกติแทน sentinel เช่น 0','fn main() { for selected in [Some(7), None] { match selected { Some(id) => println!("task={id}"), None => println!("no selection") } } }','task=7\nno selection\n','unwrap ใช้เมื่อมีเหตุผลยืนยันว่าค่ามีแน่จริง ไม่ใช่เพื่อข้ามทางผิดพลาด');
add('error/option_unwrap/question_mark','ส่ง None ต่อด้วย ?','? กับ Option คืน None ออกจากฟังก์ชันทันทีเมื่อพบ None หรือแกะ Some เพื่อทำงานต่อ','คำนวณจำนวนงานที่เหลือเมื่อ input ทั้งสองค่าอาจไม่มี','fn pending(total: Option<u32>, done: Option<u32>) -> Option<u32> { total?.checked_sub(done?) }\nfn main() { println!("{:?}", pending(Some(5), Some(2))); println!("{:?}", pending(Some(5), None)); }','Some(3)\nNone\n','Option ไม่เก็บเหตุผล ถ้าผู้ใช้ต้องรู้ว่าขาดค่าตรงไหน ให้คืน Result');
add('error/option_unwrap/map','แปลงค่าที่มีอยู่ · Option::map','map ใช้ฟังก์ชันกับค่าภายใน Some และส่ง None ผ่านไปโดยไม่เรียกฟังก์ชันนั้น','แปลงเลขงานที่เลือกให้เป็น label โดยยังเก็บสถานะไม่มีงานไว้','fn main() { for id in [Some(7), None] { println!("{:?}", id.map(|n| format!("TASK-{n:03}"))); } }','Some("TASK-007")\nNone\n','map ที่คืน Option อีกชั้นทำให้ได้ Option<Option<T>> ถ้าต้องการแบนใช้ and_then');
add('error/option_unwrap/and_then','ต่อขั้นตอนที่อาจไม่มีค่า · and_then','and_then รับฟังก์ชันที่คืน Option จึงส่ง None ผ่านและไม่ซ้อน Option เพิ่มหนึ่งชั้นเหมือน map','ข้อมูลชื่อ field อาจไม่มี หรือมีแต่ parse จำนวนงานไม่ได้','fn main() { for raw in [Some("3"), Some("oops"), None] { println!("{:?}", raw.and_then(|s| s.parse::<u32>().ok())); } }','Some(3)\nNone\nNone\n','การใช้ ok() ละทิ้งเหตุผล parse error โดยตั้งใจ ถ้าต้องเก็บให้ใช้ Result');
add('error/option_unwrap/defaults','กำหนดค่าเมื่อไม่มี · Option defaults','or รับทางเลือกที่ประเมินไว้แล้ว ส่วน or_else ประเมิน closure เมื่อ None; get_or_insert และ get_or_insert_with เติมค่าลง Option ผ่าน &mut self และคืน mutable reference','ตั้งจำนวนแถวเริ่มต้นโดยเห็นว่าค่าที่มีอยู่ไม่ถูกเขียนทับ','fn main() { let mut missing = None; let mut present = Some(20); println!("{}", missing.get_or_insert(10)); println!("{}", present.get_or_insert_with(|| 10)); println!("{:?} {:?}", missing, present); }','10\n20\nSome(10) Some(20)\n','เลือกแบบ _else หรือ _with เมื่อการสร้าง default แพงหรือมี side effect');
add('error/result','เก็บสาเหตุล้มเหลว · Result','Result<T,E> มี Ok(T) กับ Err(E) ให้ผู้เรียกรู้ทั้งค่าที่สำเร็จหรือเหตุผลที่ไม่สำเร็จ; unwrap บน Err ทำให้ panic','รับจำนวนงานจากข้อความและแยกทางผิดพลาดอย่างชัดเจน','fn parse_count(raw: &str) -> Result<u32, std::num::ParseIntError> { raw.parse() }\nfn main() { for raw in ["12", "bad"] { println!("{}", parse_count(raw).is_ok()); } }','true\nfalse\n','อย่าทำให้ Err กลายเป็นศูนย์ถ้าศูนย์เป็นข้อมูลจริงที่มีความหมายต่างจาก parse ไม่ผ่าน');
add('error/result/result_map','แปลงค่าที่สำเร็จ · Result::map','map แปลง Ok ส่วน Err ผ่านไปเดิม; and_then ใช้ต่อขั้นตอนที่คืน Result; map_err แปลงสาเหตุผิดพลาด','แปลงจำนวนงานที่ parse สำเร็จเป็นเวลาประเมินต่อรายการ','fn main() { for raw in ["3", "bad"] { let minutes = raw.parse::<u32>().map(|n| n * 5); match minutes { Ok(n) => println!("minutes={n}"), Err(_) => println!("invalid") } } }','minutes=15\ninvalid\n','การคำนวณหลัง parse ยังต้องพิจารณาช่วงตัวเลขเมื่อ input มาจากภายนอก');
add('error/result/result_alias','ย่อ Result ที่ใช้บ่อย · Type alias','type alias ย่อ Result ที่ใช้ error type เดียวกันได้ โดยไม่ได้เปลี่ยนความหมายของ Result','ฟังก์ชันอ่าน field ตัวเลขหลายตัวใน importer ใช้ error ชนิดเดียวกัน','type ParseResult<T> = Result<T, std::num::ParseIntError>;\nfn count(raw: &str) -> ParseResult<u32> { raw.parse() }\nfn main() { println!("{} {}", count("3").is_ok(), count("bad").is_ok()); }','true false\n','ชื่อ alias ควรบอกว่าเป็นผลลัพธ์ของระบบใดเมื่อหลาย error domain อยู่ใน scope เดียวกัน');
add('error/result/early_returns','คืน error ออกก่อน · Early returns','return Err(...) ออกจากฟังก์ชันทันที ทำให้แยกทางผิดพลาดก่อนเข้าส่วนคำนวณหลักได้','ตรวจ field จำนวนงานก่อนรวมผล ไม่ปล่อยข้อความผิดเข้าคำนวณ','fn doubled(raw: &str) -> Result<u32, std::num::ParseIntError> { let n = match raw.parse::<u32>() { Ok(n) => n, Err(e) => return Err(e) }; Ok(n * 2) }\nfn main() { println!("{} {}", doubled("3").is_ok(), doubled("bad").is_ok()); }','true false\n','เมื่อ error type รองรับการแปลงแล้ว ? เขียนทางส่งต่อ error ได้สั้นกว่า');
add('error/result/enter_question_mark','ส่ง Err ต่อด้วย ?','? คืนค่าจาก Ok หรือแปลงและส่ง Err ออกจากฟังก์ชันตาม From; ฟังก์ชันต้องมีชนิดผลลัพธ์ที่รองรับการใช้ ?','อ่านสอง field แล้วคำนวณงานค้าง โดยไม่ซ้อน match','fn remaining(total: &str, done: &str) -> Result<u32, std::num::ParseIntError> { let total = total.parse::<u32>()?; let done = done.parse::<u32>()?; Ok(total.saturating_sub(done)) }\nfn main() { println!("{:?}", remaining("5", "2")); println!("{}", remaining("bad", "2").is_err()); }','Ok(3)\ntrue\n','? ส่งต่อ error ไม่ได้แปลว่าจัดการ error เสร็จแล้ว จุดเรียกชั้นบนยังต้องตัดสินใจ');
add('error/multiple_error_types','เมื่อผิดได้หลายสาเหตุ · Multiple error types','ฟังก์ชันเดียวอาจผิดเพราะไม่มีข้อมูล parse ไม่ได้ หรือเงื่อนไขของโดเมนไม่ผ่าน จึงต้องออกแบบชนิดผลลัพธ์ที่แทนสาเหตุเหล่านั้นได้','อ่านรายการแรกจากชุดข้อมูลแล้ว parse จำนวนงาน ซึ่งแยกกรณีว่างกับข้อความผิดได้','fn first(items: &[&str]) -> Result<u32, &\'static str> { let raw = items.first().ok_or("empty")?; raw.parse().map_err(|_| "invalid number") }\nfn main() { println!("{:?}", first(&[])); println!("{:?}", first(&["bad"])); println!("{:?}", first(&["3"])); }','Err("empty")\nErr("invalid number")\nOk(3)\n','อย่ารวมทุกกรณีเป็นข้อความเดียวถ้าผู้เรียกต้องตัดสินใจต่างกันตามสาเหตุ');
add('error/multiple_error_types/option_result','สลับชั้น Option กับ Result','Option<Result<T,E>> กับ Result<Option<T>,E> สื่อความหมายต่างกัน; transpose สลับชั้นได้โดยรักษา None และ Err','field จำนวนงานอาจไม่ถูกระบุ แต่ถ้าระบุแล้วต้องเป็นตัวเลข','fn count(raw: Option<&str>) -> Result<Option<u32>, std::num::ParseIntError> { raw.map(str::parse).transpose() }\nfn main() { println!("{:?}", count(None)); println!("{:?}", count(Some("3"))); println!("{}", count(Some("bad")).is_err()); }','Ok(None)\nOk(Some(3))\ntrue\n','กำหนดให้ชัดว่าไม่มี field เป็นข้อผิดพลาดหรือเป็นค่า optional ตามปกติ');
add('error/multiple_error_types/define_error_type','สร้าง error ที่สื่อภาษาแอป','error ของแอปอาจเป็น enum ที่มี variant ตามสาเหตุ โดย implement Display สำหรับข้อความและ Error สำหรับสัญญา error มาตรฐาน','รายงานแยกได้ว่าข้อมูลว่างหรือเลขไม่ถูกต้อง','use std::{error::Error, fmt};\n#[derive(Debug)]\nenum ImportError { Empty, Invalid }\nimpl fmt::Display for ImportError { fn fmt(&self, f: &mut fmt::Formatter<\'_>) -> fmt::Result { write!(f, "{}", match self { Self::Empty => "empty input", Self::Invalid => "invalid count" }) } }\nimpl Error for ImportError {}\nfn main() { println!("{}", ImportError::Empty); println!("{}", ImportError::Invalid); }','empty input\ninvalid count\n','เก็บ original error เพิ่มถ้าข้อมูลวินิจฉัยนั้นจำเป็นต่อการแก้ปัญหา');
add('error/multiple_error_types/boxing_errors','รวม error ผ่าน trait object · Box<dyn Error>','Box<dyn Error> เก็บ error คนละ concrete type ผ่าน interface เดียวได้ แต่ผู้เรียกไม่ได้เห็น variant ที่ระบุสาเหตุแบบ enum ในชนิดผลลัพธ์','CLI ขนาดเล็กอ่าน field และส่ง error จากหลายขั้นตอนขึ้นชั้นบน','use std::error::Error;\nfn first(items: &[&str]) -> Result<u32, Box<dyn Error>> { let raw = items.first().ok_or("empty input")?; Ok(raw.parse()?) }\nfn main() { println!("{}", first(&["3"]).is_ok()); println!("{}", first(&[]).is_err()); println!("{}", first(&["bad"]).is_err()); }','true\ntrue\ntrue\n','เหมาะกับขอบเขตที่เน้นส่งข้อความ error ต่อ; library ที่ผู้ใช้ต้อง match สาเหตุอาจเหมาะกับ enum มากกว่า');
add('error/multiple_error_types/reenter_question_mark','? กับการแปลง error หลายชนิด','? ใช้ From แปลง error ให้ตรงชนิดผลลัพธ์ จึงลด map_err ที่เพียงห่อ error แบบเดิมซ้ำได้','แปลงข้อความเป็นจำนวนงานก่อนเพิ่มค่า โดยคืน boxed error ที่จุดเชื่อมของ CLI','use std::error::Error;\nfn next_count(raw: &str) -> Result<u32, Box<dyn Error>> { let n: u32 = raw.parse()?; Ok(n.checked_add(1).ok_or("overflow")?) }\nfn main() { println!("{:?}", next_count("3")); println!("{}", next_count("bad").is_err()); }','Ok(4)\ntrue\n','การแปลง error อัตโนมัติเกิดเมื่อมี From ที่เหมาะสม ไม่ใช่ทุก error แปลงหากันได้เสมอ');
add('error/multiple_error_types/wrap_error','เก็บ error ต้นเหตุ · Wrapping errors','error wrapper เก็บ original error เป็น field และเปิดผ่าน Error::source ได้ จึงเพิ่มบริบทพร้อมรักษาสาเหตุ','parse จำนวนงานไม่ผ่านแต่ยังเก็บสาเหตุของ parser ไว้ให้ผู้วินิจฉัย','use std::{error::Error, fmt, num::ParseIntError};\n#[derive(Debug)]\nstruct CountError(ParseIntError);\nimpl fmt::Display for CountError { fn fmt(&self, f: &mut fmt::Formatter<\'_>) -> fmt::Result { write!(f, "invalid task count: {}", self.0) } }\nimpl Error for CountError { fn source(&self) -> Option<&(dyn Error + \'static)> { Some(&self.0) } }\nfn main() { if let Err(e) = "bad".parse::<u32>().map_err(CountError) { println!("has source={}", e.source().is_some()); } }','has source=true\n','ข้อความบริบทบอกว่าอะไรล้มเหลว ส่วน source ช่วยรักษาสาเหตุทางเทคนิค');
add('error/iter_result','ประมวลผลหลายค่าที่อาจผิด · Iterating Results','collect::<Result<Vec<_>,_>>() หยุดที่ Err แรก ส่วน filter_map(Result::ok) เก็บเฉพาะค่าที่สำเร็จ; partition แยกผลลัพธ์ได้โดยไม่ทิ้งสาเหตุ','import จำนวนงานหลายบรรทัด โดยเทียบการยอมข้อมูลบางส่วนกับการปฏิเสธทั้งชุด','fn main() { let rows = ["2", "bad", "5"]; let accepted: Vec<_> = rows.iter().filter_map(|s| s.parse::<u32>().ok()).collect(); let all: Result<Vec<u32>, _> = rows.iter().map(|s| s.parse()).collect(); println!("{:?}", accepted); println!("all valid={}", all.is_ok()); }','[2, 5]\nall valid=false\n','อย่าทิ้งแถวผิดแบบเงียบ ๆ ในแอปจริงถ้าผู้ใช้ต้องรู้ว่าข้อมูลหายไปเท่าไร');
add('std','ชนิดที่พร้อมใช้ใน std','std มี String, Vec, Option, Result, Box, HashMap และ smart pointer เพื่อขยายจากชนิดพื้นฐาน หลายชนิดมี ownership และการคืนทรัพยากรในตัว','ใช้ Vec เก็บรายการงานที่เพิ่มจำนวนระหว่างรัน และ String เก็บชื่อที่อ่านจากผู้ใช้','fn main() { let mut tasks = Vec::new(); tasks.push(String::from("backup")); println!("{}", tasks.len()); tasks.push(String::from("review")); println!("{}", tasks.len()); }','1\n2\n','เลือกคอลเลกชันตามการเข้าถึงที่ต้องการ ก่อนเขียนโครงสร้างข้อมูลใหม่เอง');
add('std/box','ค่าใน heap กับ Box','Box<T> เป็นเจ้าของค่าบน heap โดยตัว handle มีขนาดทราบตอนคอมไพล์; ชนิด recursive ใช้ indirection นี้ได้ ส่วนการจัดวางจริงยังขึ้นกับ compiler optimization','ย้ายข้อมูลสรุปที่ต้องการ ownership ชัดเจนเข้า Box แล้วเข้าถึงค่าผ่าน dereference','fn main() { let mut report = Box::new(3_u32); println!("{}", *report); *report += 2; println!("{}", *report); }','3\n5\n','Box ไม่ทำให้ข้อมูลแชร์ ownership หลายเจ้าของ; หากต้องการแชร์ให้เลือกกลไกตามการใช้งาน');
add('std/vec','รายการที่โตได้ · Vec','Vec<T> เก็บสมาชิกชนิดเดียวกันใน buffer ต่อเนื่อง โดยมี length และ capacity; push เพิ่มท้าย pop หยิบท้าย และการ index นอกขอบเขต panic','เพิ่มงานใหม่แล้วลบงานท้ายออกจากรายการ','fn main() { let mut tasks = vec![2, 5]; tasks.push(8); println!("{:?}", tasks); println!("{:?}", tasks.pop()); println!("{:?}", tasks.get(9)); }','[2, 5, 8]\nSome(8)\nNone\n','การเพิ่มจนเกิน capacity อาจย้าย buffer จึงไม่เก็บ reference ไปยังสมาชิกขณะ push');
add('std/str','ข้อความ UTF-8 · String / &str','String เป็นข้อความ UTF-8 ที่เป็นเจ้าของ buffer และเปลี่ยนขนาดได้ ส่วน &str ยืมข้อความ; len นับ bytes และ chars นับ Unicode scalar values ไม่ใช่จำนวนตัวอักษรที่ผู้ใช้เห็นเสมอ','แยกจำนวน bytes ออกจากจำนวน scalar values เมื่อตรวจชื่อภาษาไทยหรืออักษรนอก ASCII','fn main() { for title in ["work", "é"] { println!("{} bytes={} chars={}", title, title.len(), title.chars().count()); } let mut title = String::from("task"); title.push_str("-1"); println!("{title}"); }','work bytes=4 chars=4\né bytes=2 chars=1\ntask-1\n','อย่า index ข้อความด้วยจำนวนเต็มเพื่อหมายถึงตัวอักษร; slice ต้องตรงขอบเขต UTF-8');
add('std/option','ค่าที่ไม่มีไม่ใช่ null · Option','Option<T> บังคับให้พิจารณา Some กับ None ผ่าน match หรือ method; เป็นชนิด enum ปกติที่ใช้กับ generic ได้','รายการงานแรกอาจไม่มีเมื่อยังไม่เพิ่มงาน','fn main() { for tasks in [vec![], vec![7]] { match tasks.first() { Some(id) => println!("first={id}"), None => println!("empty") } } }','empty\nfirst=7\n','None ควรมีความหมายเฉพาะใน API ไม่ควรใช้แทนความผิดพลาดหลายสาเหตุที่ต้องแยก');
add('std/result','ผลลัพธ์ที่มีสาเหตุ · std::result','Result เก็บ Ok หรือ Err จึงประกอบหลายขั้นตอนที่อาจล้มเหลวได้โดยไม่ทิ้งสาเหตุ','ตรวจทั้งกรณีจำนวนเป็นศูนย์ที่ถูกต้อง กับข้อความที่แปลงไม่ได้','fn main() { for raw in ["0", "bad"] { let result = raw.parse::<u32>(); match result { Ok(count) => println!("count={count}"), Err(_) => println!("parse failed") } } }','count=0\nparse failed\n','หากคืน Result ให้ผู้เรียก ให้เลือก error type ที่ตรงวิธีรับมือของผู้เรียก');
add('std/result/question_mark','ต่อหลาย Result ด้วย ?','? ส่ง error ออกในจุดแรกที่พบ และเหลือ body หลักสำหรับค่าที่สำเร็จ; ต่างจาก panic เพราะผู้เรียกยังรับ Err ได้','parse สองค่าก่อนตรวจจำนวนงานค้าง','fn remaining(total: &str, done: &str) -> Result<u32, std::num::ParseIntError> { Ok(total.parse::<u32>()?.saturating_sub(done.parse::<u32>()?)) }\nfn main() { println!("{:?}", remaining("5", "2")); println!("{}", remaining("5", "bad").is_err()); }','Ok(3)\ntrue\n','? ทำให้ทางผิดพลาดสั้นลง แต่ยังควรเพิ่มบริบทที่ขอบเขตสำคัญ');
add('std/panic','panic และการคืนทรัพยากร','เมื่อ panic แบบ unwind ค่าบนเส้นทางที่คลาย stack จะถูกทำลาย แต่กลยุทธ์ abort ไม่ทำเช่นนั้น; panic ไม่ใช่การคืน error ให้ผู้เรียกตามปกติ','จำลองสถานะงานภายในที่ไม่สอดคล้องและไม่ควรเดินหน้าต่อ','fn main() { println!("checking"); panic!("task state corrupted"); }','checking\n','อย่าใช้ catch_unwind เป็นตัวแทน Result สำหรับความล้มเหลวที่คาดหมาย','should_panic','คาดว่า stderr มี task state corrupted และ exit ไม่สำเร็จ');
add('std/hash','ค้นด้วย key · HashMap','HashMap<K,V> เก็บค่าตาม key ที่ implement Eq และ Hash; insert อาจแทนค่าเดิม get คืน Option ของ reference และลำดับ iteration ไม่รับประกัน','นับงานตามชื่อโครงการแล้วอ่านชื่อที่มีและไม่มี','use std::collections::HashMap;\nfn main() { let mut counts = HashMap::new(); counts.insert("work", 2); *counts.entry("work").or_insert(0) += 3; println!("{:?}", counts.get("work")); println!("{:?}", counts.get("home")); }','Some(5)\nNone\n','ถ้ารายงานต้องเรียงลำดับให้ sort ผลลัพธ์หรือใช้คอลเลกชันที่มีลำดับตามโจทย์');
add('std/hash/alt_key_types','ชนิดที่สร้างเองเป็น key','key ของ HashMap ต้องมี Eq และ Hash ที่สอดคล้องกัน: เมื่อสองค่าเท่ากัน hash ต้องเท่ากันด้วย; derive ช่วยสร้างจาก field ได้','แยกจำนวนงานตามคู่ผู้ใช้กับโครงการ แทนการต่อ string ที่อาจกำกวม','use std::collections::HashMap;\n#[derive(PartialEq, Eq, Hash)]\nstruct Key { user: u32, project: u32 }\nfn main() { let mut counts = HashMap::new(); counts.insert(Key { user: 1, project: 2 }, 5); println!("{:?}", counts.get(&Key { user: 1, project: 2 })); println!("{:?}", counts.get(&Key { user: 1, project: 3 })); }','Some(5)\nNone\n','อย่าแก้ส่วนของ key ที่มีผลต่อ Eq/Hash ขณะที่ยังเป็น key อยู่ใน map');
add('std/hash/hashset','สมาชิกที่ไม่ซ้ำ · HashSet','HashSet<T> เก็บสมาชิกตาม Eq และ Hash โดยไม่ผูก value; มี union intersection difference และ symmetric_difference สำหรับเปรียบเทียบชุด','รวมเลขงานที่ถูกเลือกจากสองแหล่งแล้วกำจัดค่าซ้ำ','use std::collections::HashSet;\nfn main() { let a: HashSet<_> = [1, 2].into_iter().collect(); let b: HashSet<_> = [2, 3].into_iter().collect(); let mut ids: Vec<_> = a.union(&b).copied().collect(); ids.sort(); println!("{:?}", ids); println!("{}", a.intersection(&b).count()); }','[1, 2, 3]\n1\n','sort ก่อนแสดงผลเมื่อจำเป็นต้องได้ลำดับแน่นอน');
add('std/rc','แชร์ ownership ใน thread เดียว · Rc','Rc<T> นับ strong references แบบไม่ atomic clone เพิ่มเจ้าของข้อมูลเดิม และข้อมูลถูกทำลายเมื่อ strong count เป็นศูนย์; Rc ไม่ใช่เครื่องมือแชร์ข้าม thread','มุมมองรายงานสองตัวใช้ชื่อโครงการเดียวกันโดยไม่ clone เนื้อหา String','use std::rc::Rc;\nfn main() { let name = Rc::new(String::from("work")); println!("{}", Rc::strong_count(&name)); let view = Rc::clone(&name); println!("{} {}", view, Rc::strong_count(&name)); drop(view); println!("{}", Rc::strong_count(&name)); }','1\nwork 2\n1\n','วงจร strong references อาจทำให้ไม่ถูกคืน ใช้ Weak เมื่อความสัมพันธ์ไม่ควรเป็นเจ้าของ');
add('std/arc','แชร์ ownership ข้าม thread · Arc','Arc<T> ใช้ atomic reference counting; การแชร์ข้าม thread ยังขึ้นกับ Send/Sync ของ T และ Arc ไม่ได้ให้สิทธิ์แก้ T พร้อมกันโดยอัตโนมัติ','ส่งชื่อโครงการให้ worker โดย worker เป็นเจ้าของ Arc อีกหนึ่งตัว','use std::{sync::Arc, thread};\nfn main() { let name = Arc::new(String::from("work")); let worker_name = Arc::clone(&name); let worker = thread::spawn(move || worker_name.len()); match worker.join() { Ok(n) => println!("{} {n}", name), Err(_) => println!("worker failed") } }','work 4\n','ถ้าต้องแก้ข้อมูลร่วมกัน ให้เลือก synchronization ที่เหมาะสม เช่น Mutex และตรวจผล lock');
add('std_misc','ทำงานกับระบบภายนอก · Std misc','std มี thread, channel, file, process และ path เพื่อให้โปรแกรมทำงานกับระบบปฏิบัติการ ขั้นตอนเหล่านี้อาจล้มเหลวต่างจากคำนวณค่าล้วน','ใช้ worker คำนวณจำนวนงานแล้วรับผลกลับก่อนสร้างรายงาน','fn main() { let worker = std::thread::spawn(|| [2_u32, 3].iter().sum::<u32>()); match worker.join() { Ok(total) => println!("total={total}"), Err(_) => println!("worker failed") } }','total=5\n','ตรวจ Result ที่ขอบเขตระบบภายนอก และอย่าสมมติลำดับการทำงานของ thread');
add('std_misc/threads','แยกงานไป thread · Threads','thread::spawn เริ่ม thread พร้อม closure; JoinHandle::join รอให้เสร็จและคืน Result เพราะ thread อาจ panic; ลำดับการพิมพ์จากหลาย threadไม่แน่นอน','คำนวณจำนวนงานสองชุดแล้วรวมเมื่อ worker เสร็จ แทนการคาดเดาว่า worker ใดเสร็จก่อน','use std::thread;\nfn main() { let a = thread::spawn(|| 2_u32 + 3); let b = thread::spawn(|| 4_u32); match (a.join(), b.join()) { (Ok(a), Ok(b)) => println!("total={}", a + b), _ => println!("worker failed") } }','total=9\n','การแตกงานเล็กมากอาจเสียเวลาเริ่มและประสาน thread มากกว่าคำนวณ');
add('std_misc/threads/testcase_mapreduce','แบ่งข้อมูลแล้วรวมผล · Map-reduce','map-reduce แบ่ง input ให้ worker คำนวณผลย่อย แล้ว reduce รวมผล; ต้องคิดถึงต้นทุนแบ่งงานและความถูกต้องของการรวม ไม่ใช่แค่จำนวน thread','แบ่งจำนวนงานรายวันเป็นสองช่วง คำนวณผลรวมแต่ละช่วงแล้วรวมกัน','use std::thread;\nfn main() { let chunks = [vec![2_u32, 3], vec![4, 1]]; let handles: Vec<_> = chunks.into_iter().map(|chunk| thread::spawn(move || chunk.iter().sum::<u32>())).collect(); let mut total = 0; for handle in handles { match handle.join() { Ok(part) => total += part, Err(_) => { println!("worker failed"); return; } } } println!("total={total}"); }','total=10\n','วัดกับข้อมูลจริงก่อนสรุปว่า parallel เร็วกว่า sequential');
add('std_misc/channels','ส่งข้อมูลระหว่าง thread · Channels','std::sync::mpsc::channel ให้ Sender กับ Receiver; ส่งได้ทางเดียว clone Sender เพิ่มผู้ส่ง และ recv คืน error เมื่อไม่มีผู้ส่งที่ยังเปิดและไม่มีข้อมูลเหลือ','worker ส่งจำนวนงานที่คำนวณเสร็จมาให้ตัวสร้างรายงาน','use std::{sync::mpsc, thread};\nfn main() { let (tx, rx) = mpsc::channel(); let worker = thread::spawn(move || tx.send(5_u32)); match rx.recv() { Ok(n) => println!("count={n}"), Err(_) => println!("channel closed") } println!("worker ok={}", matches!(worker.join(), Ok(Ok(())))); }','count=5\nworker ok=true\n','อย่ารอ recv จาก channel ที่ยังมี Sender เก็บไว้แต่จะไม่ส่งข้อมูลอีก เพราะอาจรอไม่จบ');
add('std_misc/path','จัดเส้นทางไฟล์ · Path / PathBuf','Path เป็นมุมมองยืมของเส้นทาง PathBuf เป็นเจ้าของเส้นทางที่แก้ได้; เส้นทางไม่จำเป็นต้องเป็น UTF-8 และการ join ไม่ตรวจว่าไฟล์มีอยู่จริง','ต่อชื่อไฟล์ตั้งค่าโดยไม่ต่อ string ด้วย separator เอง','use std::path::Path;\nfn main() { for name in ["tasks.csv", "settings.toml"] { let path = Path::new("data").join(name); println!("{:?}", path.extension().and_then(|v| v.to_str())); } }','Some("csv")\nSome("toml")\n','ถ้าชื่อไฟล์มาจากผู้ใช้ ต้องตรวจข้อจำกัดการเข้าถึง path ตามบริบทแอป');
add('std_misc/file','อ่านเขียนไฟล์ด้วย Result · File I/O','File เป็นเจ้าของ handle ของไฟล์; การเปิดอ่านเขียนคืน Result เพราะไฟล์อาจหาย สิทธิ์ไม่พอ หรืออุปกรณ์ผิดพลาด; Drop คืน handle แต่ไม่ได้รับประกันการ sync ข้อมูลถาวร','parser อ่านข้อมูลตั้งค่าได้จากตัวอ่านที่มีสัญญา Read โดยแยกจากการเปิดไฟล์จริง','use std::io::{self, Read};\nfn read_count(mut input: impl Read) -> io::Result<String> { let mut text = String::new(); input.read_to_string(&mut text)?; Ok(text) }\nfn main() -> io::Result<()> { println!("{}", read_count(&b"3"[..])?); println!("{}", read_count(&b"5"[..])?); Ok(()) }','3\n5\n','แยกการอ่าน bytes ออกจากการตีความค่าของแอป เพื่อรายงาน error ได้ตรงขั้นตอน');
add('std_misc/file/open','เปิดไฟล์เพื่ออ่าน · File::open','File::open เปิดไฟล์แบบอ่านอย่างเดียวและคืน io::Result; read_to_string ต้องการข้อมูล UTF-8 ที่ถูกต้อง','ตัวอย่างสร้างไฟล์ชั่วคราวเฉพาะการสาธิต จากนั้นเปิดอ่านจำนวนงานและลบออก','use std::{fs::{self, File}, io::{self, Read}};\nfn main() -> io::Result<()> { let path = std::env::temp_dir().join(format!("rbe-open-{}.txt", std::process::id())); let mut created = fs::OpenOptions::new().write(true).create_new(true).open(&path)?; use std::io::Write; created.write_all(b"3")?; drop(created); let mut text = String::new(); File::open(&path)?.read_to_string(&mut text)?; fs::remove_file(&path)?; println!("count={text}"); Ok(()) }','count=3\n','ในแอปจริงอย่าสร้างไฟล์ทับเองเพื่อแก้กรณี File::open ไม่สำเร็จ ให้แยก NotFound ออกจากข้อผิดพลาดอื่น');
add('std_misc/file/create','สร้างไฟล์โดยรู้ผลของการเขียนทับ · create','File::create สร้างไฟล์ใหม่หรือ truncate ไฟล์เดิมให้ว่างทันที; write_all พยายามเขียนข้อมูลทั้งหมดและคืน error หากทำไม่ได้','เมื่อ export ต้องการป้องกันไฟล์เดิม ใช้ OpenOptions::create_new(true) เพื่อให้การสร้างล้มเหลวแทนเขียนทับ','use std::{fs::{self, OpenOptions}, io::{self, Write}};\nfn main() -> io::Result<()> { let path = std::env::temp_dir().join(format!("rbe-create-{}.txt", std::process::id())); let mut file = OpenOptions::new().write(true).create_new(true).open(&path)?; file.write_all(b"tasks=3\n")?; drop(file); let text = fs::read_to_string(&path)?; fs::remove_file(&path)?; print!("{text}"); Ok(()) }','tasks=3\n','ตกลงนโยบายเขียนทับให้ชัดก่อนใช้ File::create กับข้อมูลผู้ใช้');
add('std_misc/file/read_lines','อ่านทีละบรรทัด · BufRead::lines','BufReader ช่วย buffer การอ่าน ส่วน lines() คืน iterator ของ io::Result<String> จึงต้องตรวจ error ในแต่ละบรรทัดด้วย; read_to_string อ่านทั้งไฟล์เข้าหน่วยความจำ','สรุปจำนวนงานจากข้อมูลหลายบรรทัดโดยใช้ Cursor เป็นไฟล์จำลองที่อ่านซ้ำได้','use std::io::{self, BufRead, Cursor};\nfn main() -> io::Result<()> { for line in Cursor::new(b"2\n5\n").lines() { let text = line?; match text.parse::<u32>() { Ok(n) => println!("tasks={n}"), Err(_) => println!("invalid count") } } Ok(()) }','tasks=2\ntasks=5\n','อย่าใช้ filter_map(Result::ok) ถ้าข้อผิดพลาดอ่านไฟล์ไม่ควรถูกกลืนหาย');
add('std_misc/process','เรียกโปรแกรมลูก · Command','Command สร้าง process โดยกำหนด executable และ arguments แยกกัน; output รอให้จบพร้อมเก็บ stdout stderr และ status; การ spawn สำเร็จไม่ได้แปลว่าโปรแกรมลูกทำงานสำเร็จ','ตัวอย่างเรียก executable ตัวเองในโหมด worker จึงไม่ต้องพึ่ง shell หรือคำสั่งของระบบใดระบบหนึ่ง','use std::{io, process::Command};\nfn main() -> io::Result<()> { if std::env::args().any(|a| a == "--worker") { println!("tasks=5"); return Ok(()); } let out = Command::new(std::env::current_exe()?).arg("--worker").output()?; println!("success={}", out.status.success()); print!("{}", String::from_utf8_lossy(&out.stdout)); Ok(()) }','success=true\ntasks=5\n','ใช้ arg แยกจากชื่อโปรแกรม และตรวจ exit status ก่อนใช้ stdout เป็นข้อมูลที่เชื่อถือได้');
add('std_misc/process/pipe','ต่อ stdin/stdout ผ่าน pipe','Stdio::piped เปิด handle ให้ parent ส่งหรือรับข้อมูลกับ child; ต้องปิด stdin เมื่อส่งเสร็จเพื่อให้ child ที่อ่านจน EOF ทำงานต่อได้','ส่งชื่อรายงานเข้า worker แล้วรับข้อความที่แปลงกลับมา','use std::{io::{self, Read, Write}, process::{Command, Stdio}};\nfn main() -> io::Result<()> { if std::env::args().any(|a| a == "--worker") { let mut input = String::new(); io::stdin().read_to_string(&mut input)?; print!("{}", input.to_uppercase()); return Ok(()); } let mut child = Command::new(std::env::current_exe()?).arg("--worker").stdin(Stdio::piped()).stdout(Stdio::piped()).spawn()?; if let Some(mut input) = child.stdin.take() { input.write_all(b"work\n")?; } let out = child.wait_with_output()?; if out.status.success() { print!("{}", String::from_utf8_lossy(&out.stdout)); } else { println!("worker failed"); } Ok(()) }','WORK\n','อ่านเขียนข้อมูลจำนวนมากต้องออกแบบไม่ให้ทั้งสองฝั่งรอกันจน pipe เต็ม');
add('std_misc/process/wait','รอ child จบ · Child::wait','Child::wait รอ process จบและคืน ExitStatus; การ drop Child ไม่ได้รอให้มันจบโดยอัตโนมัติ','ก่อนแจ้ง export เสร็จ ต้องรอ worker และดูว่าจบสำเร็จจริง','use std::{io, process::Command};\nfn main() -> io::Result<()> { if std::env::args().any(|a| a == "--worker") { return Ok(()); } let mut child = Command::new(std::env::current_exe()?).arg("--worker").spawn()?; println!("success={}", child.wait()?.success()); Ok(()) }','success=true\n','หากไม่ใช้ output() หรือ wait_with_output() ต้องวางจุด wait ให้ชัดเอง');
add('std_misc/fs','งานกับระบบไฟล์ · std::fs','std::fs มี create_dir, read_dir, copy, rename, remove_file และ remove_dir; แต่ละคำสั่งอาจล้มเหลวและความสามารถบางอย่างต่างกันตามระบบปฏิบัติการ','ทำโฟลเดอร์รายงานชั่วคราว ตรวจว่ามีจริง แล้วลบเฉพาะโฟลเดอร์ว่างที่ตัวอย่างสร้าง','use std::{fs, io};\nfn main() -> io::Result<()> { let path = std::env::temp_dir().join(format!("rbe-dir-{}", std::process::id())); fs::create_dir(&path)?; println!("directory={}", fs::metadata(&path)?.is_dir()); fs::remove_dir(&path)?; println!("exists={}", path.exists()); Ok(()) }','directory=true\nexists=false\n','การเช็กว่ามีไฟล์แล้วค่อยทำงานไม่กัน race; ใช้ operation ที่รับประกันเงื่อนไขนั้น เช่น create_new เมื่อสร้างไฟล์');
add('std_misc/arg','อ่าน argument ของโปรแกรม','std::env::args คืน iterator ของ String และตัวแรกตามปกติเป็นชื่อหรือ path ของโปรแกรม; args_os รองรับ argument ที่ไม่ใช่ UTF-8','ตัวอย่างจำลองค่าจาก args เพื่อให้เห็นความต่างระหว่างชื่อโปรแกรมกับตัวเลือกของผู้ใช้','fn main() { let args = ["tasks", "list", "work"]; for (index, arg) in args.iter().enumerate() { println!("{index}={arg}"); } }','0=tasks\n1=list\n2=work\n','โค้ดนี้ใช้ชุด argument จำลองเพื่อให้ผลซ้ำได้ เมื่อต่อ CLI จริงใช้ env::args หรือ args_os');
add('std_misc/arg/matching','แปลคำสั่งจาก pattern · Argument parsing','match บน slice ของ argument แยกคำสั่งและจำนวน parameter ได้ แล้ว parse ค่าที่ต้องมีชนิด; pattern ไม่ได้ตรวจความหมายของข้อความให้','รองรับ list ที่ไม่ต้องมีเลข และ show ที่ต้องมีเลขงานถูกต้อง','fn command(args: &[&str]) { match args { ["list"] => println!("all tasks"), ["show", id] => match id.parse::<u32>() { Ok(id) => println!("task={id}"), Err(_) => println!("invalid id") }, _ => println!("usage") } }\nfn main() { command(&["list"]); command(&["show", "7"]); command(&["show", "bad"]); }','all tasks\ntask=7\ninvalid id\n','เมื่อคำสั่ง ตัวเลือก และ help ซับซ้อน ค่อยประเมิน parser library จากเอกสารจริง');
add('std_misc/ffi','เรียก native library · FFI','extern block ประกาศ signature ของ foreign function และ link ระบุ library; การเรียก foreign function โดยทั่วไปเป็น unsafe เพราะ compiler พิสูจน์สัญญาฝั่งภายนอกไม่ได้ ต้องตรวจ ABI ชนิด และ precondition','ตัวอย่างอ่านค่า cosine จาก libm แสดงการเชื่อม native library; ไม่ได้จำเป็นสำหรับแอปจัดการงานทั่วไป','// ตัวอย่างเฉพาะ target ที่มี libm และ C double ตรงกับ f64\n#[link(name = "m")]\nextern "C" { fn cos(x: f64) -> f64; }\nfn main() {\n    // SAFETY: signature ต้องตรงกับ libm บน target ที่เลือก\n    let value = unsafe { cos(0.0) };\n    println!("{value}");\n}','1\n','ทำ safe wrapper หลังตรวจสัญญาของ native API ทุกข้อ และระบุ target ที่ทดสอบจริง','text','ต้อง link libm บน target ที่รองรับและตรวจ ABI; เป็นตัวอย่าง platform-specific ที่ยังไม่ผ่าน native build');
add('testing','ตรวจพฤติกรรมด้วยการทดสอบ · Testing','Rust รองรับ unit test, integration test และ documentation test โดย Cargo ช่วย compile และรัน; เมื่อทดสอบผลคำนวณ ควร assert ผลที่ต้องการ ไม่ใช่เพียงเรียกฟังก์ชันแล้วไม่ตรวจค่า','ตรวจการนับงานที่เสร็จและกรณียังไม่มีงาน เพื่อป้องกันผลรายงานผิดหลังแก้โค้ด','fn pending(total: u32, done: u32) -> u32 { total.saturating_sub(done) }\nfn main() { assert_eq!(pending(5, 2), 3); assert_eq!(pending(0, 0), 0); println!("checks passed"); }','checks passed\n','assert ยืนยันกรณีที่กำหนดไว้ ไม่ใช่หลักฐานว่าทุก input ถูกต้อง');
add('testing/unit_testing','ตรวจหน่วยเล็กของโค้ด · Unit testing','#[test] ระบุฟังก์ชันทดสอบ; assert!, assert_eq!, assert_ne! ตรวจเงื่อนไข #[should_panic] ระบุการ panic ที่คาดหมาย #[ignore] ข้ามโดยปริยาย และ test คืน Result ได้; #[cfg(test)] แยก test module จาก build ปกติ','วางชุดตรวจตรรกะจำนวนงานข้าง implementation เพื่อเรียก private helper ได้','// src/lib.rs\nfn pending(total: u32, done: u32) -> u32 { total.saturating_sub(done) }\n#[cfg(test)]\nmod tests {\n    use super::pending;\n    #[test]\n    fn remaining_tasks() {\n        assert_eq!(pending(5, 2), 3);\n        assert_eq!(pending(0, 0), 0);\n    }\n}','','ตรวจพฤติกรรมที่เสี่ยงพังและขอบเขต input; should_panic ควรระบุ expected เพื่อไม่ยอมรับ panic คนละสาเหตุ','text','วางใน Cargo library แล้วรัน cargo test; โค้ดนี้ต้องใช้ test harness ไม่ใช่ main executable');
add('testing/doc_testing','ตัวอย่างในเอกสารเป็น test ได้ · Doc tests','rustdoc ใช้ Rust code block ใน doc comments เป็น test โดยปริยายเมื่อ cargo test; # ซ่อนบรรทัดจากหน้าที่แสดงแต่ยังคอมไพล์; no_run ตรวจ compile โดยไม่ run ส่วน compile_fail คาดว่าคอมไพล์ไม่ผ่าน','ตัวอย่างใช้ public API รายงานอยู่ใกล้คำอธิบาย จึงตรวจได้ว่า API ยังใช้ตามเอกสารได้','// src/lib.rs ของ package task_core\n/// Count tasks not yet finished.\n///\n/// ```\n/// assert_eq!(task_core::pending(5, 2), 3);\n/// assert_eq!(task_core::pending(0, 0), 0);\n/// ```\npub fn pending(total: u32, done: u32) -> u32 { total.saturating_sub(done) }','','อย่าใช้ ignore กลบตัวอย่างที่ล้าสมัยถ้าจริง ๆ ต้องแก้ให้ compile ได้','text','ต้องใช้ package ชื่อ task_core และรัน cargo test --doc; snippet อ้างชื่อ crate ตาม package นี้');
add('testing/integration_testing','ตรวจจากมุมผู้ใช้ crate · Integration tests','ไฟล์ .rs ระดับ tests/ เป็น crate ทดสอบแยก เข้าถึงได้ผ่าน public API; helper หลายไฟล์ใช้ tests/common/mod.rs เพื่อลดการถูกมองเป็น test target แยก','ตรวจ API ที่ CLI หรือโปรแกรมอื่นใช้จริง โดยไม่พึ่ง private implementation','// tests/report.rs ของ package task_core\nuse task_core::pending;\n#[test]\nfn public_report_counts() {\n    assert_eq!(pending(5, 2), 3);\n    assert_eq!(pending(5, 5), 0);\n}','','การทดสอบ integration ที่เข้าถึง public API ช่วยตรวจว่า consumer เรียกใช้งานได้จริง','text','ต้องมี task_core::pending เป็น pub ใน src/lib.rs และรัน cargo test');
add('testing/dev_dependencies','dependency เฉพาะงานพัฒนา','[dev-dependencies] ใช้กับ tests, examples และ benchmarks โดยไม่เป็น dependency ที่ consumer ใช้ build library ตามปกติ','ถ้าชุดทดสอบต้องใช้ helper crate ให้แยกจาก runtime dependency เพื่อไม่ทำให้ขอบเขต library ปะปน','# Cargo.toml\n[dev-dependencies]\ntest_support = { path = "../test_support" }\n\n# ต้องมี package test_support จริงที่เส้นทางนี้','','ไม่ต้องเพิ่ม dependency เมื่อ standard assert และข้อมูลทดสอบขนาดเล็กพอแล้ว','text','ตัวอย่าง manifest สำหรับโครงการหลาย crate ต้องมี test_support อยู่จริงก่อน cargo test');
add('unsafe','รับหน้าที่พิสูจน์เพิ่ม · Unsafe Operations','unsafe อนุญาตการทำงานบางอย่างที่ safe Rust ไม่ยอม เช่น dereference raw pointer เรียก unsafe function เข้าถึง mutable static และอ่าน union field; borrow checking ส่วนอื่นยังทำงานตามปกติ และผู้เขียนต้องพิสูจน์สัญญาความปลอดภัย','ดู raw pointer ที่สร้างจาก reference ซึ่งยังมีชีวิต โดยไม่มีเหตุผลให้ใช้ unsafe แทน &value ในแอปทั่วไป','fn main() {\n    let count = 3_u32;\n    let pointer = &count as *const u32;\n    // SAFETY: pointer มาจาก reference ที่ยังถูกต้องและ count ยังมีชีวิต\n    let read = unsafe { *pointer };\n    println!("{read}");\n}','','ในโค้ดแอปทั่วไปให้อยู่กับ safe API; unsafe ต้องอธิบาย precondition ทุกข้อ ไม่ใช่แค่ใส่บล็อกให้ compiler ยอม','text','ตัวอย่าง raw pointer ยังไม่ผ่าน compiler/runtime check จึงไม่แสดงผลลัพธ์ว่าได้รับการพิสูจน์แล้ว; ค่าที่คาดคือ 3');
add('unsafe/asm','แทรก assembly · Inline assembly','asm! รองรับ assembly ที่ผูกกับสถาปัตยกรรม ต้องประกาศ input/output registers และ side effects ให้ compiler รู้ in/out/inout กับ lateout มีข้อจำกัดการใช้ register ต่างกัน; const และ sym ใช้ค่าคงที่หรือ symbol ส่วน clobber_abi ระบุ register ที่ ABI อาจเปลี่ยน','การอ่าน register หรือคำสั่งเฉพาะเครื่องเหมาะกับงานระดับระบบที่มีข้อจำกัดชัดเจน ไม่จำเป็นสำหรับแอปงานทั่วไป ตัวอย่างคำนวณค่าบน x86_64 เท่านั้น','// เฉพาะ target_arch = "x86_64"\nuse std::arch::asm;\nfn main() {\n    let mut value: u64 = 3;\n    // SAFETY: ทำงานเฉพาะ register ที่ประกาศและไม่เข้าถึงหน่วยความจำ\n    unsafe { asm!("add {value}, 2", value = inout(reg) value); }\n    println!("{value}");\n}','5\n','options เช่น nomem, nostack, preserves_flags และ pure เป็นสัญญาที่ต้องเป็นจริง; อย่าระบุเพื่อหวังให้เร็วขึ้นโดยไม่มีหลักฐาน','text','ต้องทดสอบบน x86_64 และ compiler ที่รองรับ; ยังไม่ผ่าน target-specific compilation จึงไม่ถือว่า verified');
add('compatibility','โค้ดอยู่ร่วมกับภาษาที่เปลี่ยนไป · Compatibility','Rust เพิ่ม keyword และรูปแบบใหม่ผ่านการพัฒนาภาษาและ editions จึงต้องดู edition ของ crate และเอกสารที่อ้างอิงให้สอดคล้องกัน','ระบุ edition ใน manifest เพื่อให้ทีมและระบบ build ใช้กฎภาษาเดียวกัน','[package]\nname = "task_app"\nversion = "0.1.0"\nedition = "2021"','','edition ต่างจากเวอร์ชัน compiler; crate edition เดิมยังใช้ compiler ใหม่ที่รองรับได้','text','TOML สำหรับ Cargo; ตัวอย่าง Rust ที่ตรวจอัตโนมัติในโครงการนี้ระบุ edition แยกใน metadata');
add('compatibility/raw_identifiers','ชื่อชน keyword · Raw identifiers','r#name ทำให้ใช้ keyword บางคำเป็น identifier ได้ เช่น r#type; รูปแบบ raw ไม่ได้เปลี่ยนชื่อจริงของ identifier และใช้ไม่ได้กับทุกชื่อพิเศษ','ข้อมูลที่มี field ชื่อ type จากระบบเดิมยังตั้งชื่อใน Rust ให้สอดคล้องได้','struct Task { r#type: &\'static str }\nfn main() { for kind in ["backup", "report"] { let task = Task { r#type: kind }; println!("{}", task.r#type); } }','backup\nreport\n','ถ้าตั้ง API ใหม่เองได้ เลือกชื่อเฉพาะความหมายเช่น task_kind เพื่ออ่านง่าย');
add('meta','เครื่องมือที่ช่วยคนอ่านโค้ด · Meta','เอกสารและตัวอย่างที่ทดลองได้ช่วยให้ผู้ใช้เข้าใจ API แม้ไม่เปลี่ยนผล runtime ของแอปโดยตรง','เก็บคำอธิบาย ข้อจำกัด และตัวอย่างเรียก API ของการนับงานไว้ด้วยกัน','/// Return the number of pending tasks, clamped at zero.\nfn pending(total: u32, done: u32) -> u32 { total.saturating_sub(done) }\nfn main() { println!("{} {}", pending(5, 2), pending(2, 5)); }','3 0\n','เอกสารควรบอกกรณีผิดพลาดและข้อสมมติ ไม่ใช่บอกแค่ชื่อ argument ซ้ำ');
add('meta/doc','สร้างเอกสารจากโค้ด · rustdoc','cargo doc สร้างเอกสารใน target/doc และ --open เปิดใน browser; /// อธิบาย item ถัดไป //! อธิบาย enclosing module/crate; doc attributes ควบคุมการแสดงผล และ cargo test --doc ตรวจตัวอย่างในเอกสาร','ให้ API ของ library อธิบายพฤติกรรมเมื่อจำนวนที่ทำเสร็จเกินทั้งหมด เพื่อไม่ให้ consumer เดาเอง','// src/lib.rs ของ task_core\n/// Count unfinished tasks, returning zero when done exceeds total.\n///\n/// # Examples\n/// ```\n/// assert_eq!(task_core::pending(5, 2), 3);\n/// assert_eq!(task_core::pending(2, 5), 0);\n/// ```\npub fn pending(total: u32, done: u32) -> u32 { total.saturating_sub(done) }','','ใช้ doc(hidden) ซ่อนรายละเอียดจากเอกสารได้ แต่ไม่ได้ทำให้ public item เป็น private','text','ใช้ cargo doc --open และ cargo test --doc ใน package task_core ที่มี lib.rs นี้');
add('meta/playground','ลองโค้ดผ่านเว็บ · Playground','Rust Playground ใช้ทดลองโค้ดในเว็บได้; mdBook ทำ code block ให้ editable/runnable ได้ ส่วน rustdoc กำหนด html_playground_url เพื่อเชื่อมตัวอย่างกับบริการ; การรันผ่านบริการต้องใช้อินเทอร์เน็ต','เว็บนี้เก็บโค้ดและผลลัพธ์ที่คาดไว้ให้อ่านออฟไลน์ โดยไม่อ้างว่าได้เรียก Playground ทุกครั้งที่อ่าน','fn main() {\n    for done in [2_u32, 5] {\n        println!("pending={}", 5_u32.saturating_sub(done));\n    }\n}','pending=3\npending=0\n','การรันในเว็บเป็นเพียงเครื่องมือทดลอง ต้องระบุ compiler edition และตรวจเงื่อนไข target ของโค้ดด้วย');
for (const [id, code, expectedError] of [
 ['scope/move', 'fn main() {\n    let draft = String::from("backup");\n    let saved = draft;\n    println!("{draft} {saved}");\n}', 'E0382'],
 ['scope/borrow/alias', 'fn main() {\n    let mut tasks = vec![1];\n    let view = &tasks;\n    tasks.push(2);\n    println!("{:?}", view);\n}', 'E0502'],
 ['generics/new_types', 'struct TaskId(u32);\nstruct UserId(u32);\nfn open_task(_: TaskId) {}\nfn main() {\n    open_task(UserId(3));\n}', 'E0308']
]) {
 rows.find(row=>row.id===id).extraExamples=[{title:'เมื่อเปลี่ยนโค้ดจนผิดสัญญา',code,expected:'',mode:'compile_fail',edition:'2021',expectedError,note:'ตัวอย่างตั้งใจให้คอมไพล์ไม่ผ่าน ต้องตรวจรหัสข้อผิดพลาดตามที่ระบุ ไม่ใช่ยอมรับ error ใดก็ได้'}];
}
const unsafeRow=rows.find(row=>row.id==='unsafe');
unsafeRow.mode='run'; unsafeRow.expected='3\n'; unsafeRow.note='อ่าน raw pointer ที่สร้างจาก reference ซึ่งยัง valid เท่านั้น; ผลคาดหมายต้องผ่าน compiler/runtime check ก่อนแสดงว่าตรวจแล้ว';
